'use client';
import React from 'react';
type Ex={q:string;steps:string[];answer:string};
type S={title:string;body:string[];board?:string[];example?:Ex;examples?:Ex[]};
type Lesson={title:string;objectives:string[];sections:S[];mistakes:string[]};
const lessons:Record<string,Lesson>={
"Square Root of Numbers":{title:"Square Root of Numbers",objectives:["Explain what squaring a number means and connect a square to area","Identify perfect squares and distinguish them from non-perfect squares","Find squares of whole numbers and decimals","Explain square root as the inverse of squaring","Find square roots of perfect squares by inspection and by prime-factor method","Estimate the square root of a non-perfect square between consecutive whole numbers","Solve quantitative reasoning and real-life problems involving squares and square roots"],sections:[
{title:"1. Foundation: what does it mean to square a number?",body:["Before using the square-root sign, understand the idea that creates a square. If a square has side length 4 units, it contains 4 rows of 4 unit squares. Its area is 4 × 4 = 16 square units. We write this as 4² = 16.","The small raised 2 is called an exponent or index. It tells us to use the number as a factor twice. Therefore 7² means 7 × 7, not 7 × 2.","This gives a useful picture: squaring a positive number can be understood as finding the area of a square whose side is that number."] ,example:{q:"Find 12² and explain what the notation means.",steps:["12² means that 12 is used as a factor two times.","Write the multiplication explicitly: 12 × 12.","Multiply: 12 × 12 = 144.","Therefore 12² = 144.","Check the meaning: a square of side 12 units would have area 144 square units."],answer:"12² = 144"},examples:[{q:"Find 35².",steps:["35² means 35 × 35.","35 × 30 = 1,050 and 35 × 5 = 175.","1,050 + 175 = 1,225.","Check: the result lies between 30²=900 and 40²=1,600."],answer:"35² = 1,225"},{q:"Find 105².",steps:["105² = 105 × 105.","105 × 100 = 10,500.","105 × 5 = 525.","Add: 10,500 + 525 = 11,025."],answer:"105² = 11,025"}]},
{title:"2. Perfect squares: build the pattern instead of memorising blindly",body:["A perfect square is a number obtained by multiplying a whole number by itself. Examples are 1, 4, 9, 16 and 25 because they are 1², 2², 3², 4² and 5².","The sequence continues: 6²=36, 7²=49, 8²=64, 9²=81, 10²=100, 11²=121, 12²=144, 13²=169, 14²=196, 15²=225, 16²=256, 17²=289, 18²=324, 19²=361, 20²=400.","Numbers such as 50 and 70 are not perfect squares because no whole number multiplied by itself gives exactly 50 or 70. Knowing neighbouring perfect squares later helps us estimate their square roots."]},
{title:"3. Squaring larger numbers: make every operation visible",body:["When mental multiplication is not immediate, use a known multiplication method. The exponent does not change the multiplication rules."],example:{q:"Find 23².",steps:["23² means 23 × 23.","Split the second 23 into 20 + 3.","23 × 20 = 460.","23 × 3 = 69.","Add the two partial products: 460 + 69 = 529.","Therefore 23² = 529.","Check: 529 is larger than 20²=400 and smaller than 30²=900, so the size is reasonable."],answer:"23² = 529"}},
{title:"4. Decimal squares",body:["Decimals can also be squared. Multiply the number by itself and keep the place value correct. A useful check is size: if a positive number is less than 1, its square is even smaller."],example:{q:"Find 0.6².",steps:["0.6² means 0.6 × 0.6.","Ignoring the decimal points for a moment, 6 × 6 = 36.","There is one decimal place in each factor, so the product has two decimal places.","36 becomes 0.36.","Check: 0.6 is less than 1, so its square 0.36 should also be less than 1."],answer:"0.6² = 0.36"},examples:[{q:"Find 1.2².",steps:["1.2² = 1.2 × 1.2.","12 × 12 = 144.","There are two decimal places altogether, so write 1.44.","Check: since 1.2 is greater than 1, its square should be greater than 1."],answer:"1.2² = 1.44"},{q:"Find 0.04².",steps:["0.04 × 0.04 uses 4 × 4 = 16.","There are four decimal places altogether.","Write 0.0016.","Check: squaring a positive number below 1 makes it smaller."],answer:"0.04² = 0.0016"}]},
{title:"5. Square root: reverse the squaring process",body:["A square root asks the reverse question. If 9² = 81, then the positive square root of 81 is 9. We write √81 = 9.","The radical symbol √ means square root. At this level, when AVORA writes √81, we mean the principal, non-negative square root.","Do not confuse square root with dividing by 2. √36 is 6 because 6 × 6 = 36; 36 ÷ 2 = 18 answers a completely different question."],example:{q:"Find √169.",steps:["Ask: which positive whole number multiplied by itself gives 169?","Recall nearby perfect squares: 12²=144 and 13²=169.","Since 13 × 13 = 169, 13 is the positive number whose square is 169.","Therefore √169 = 13.","Check by reversing the operation: 13² = 169."],answer:"√169 = 13"}},
{title:"6. Why the prime-factor method works",body:["Inspection is easy for familiar perfect squares, but the curriculum also requires the factor method. First break the number completely into prime factors.","A perfect square contains prime factors in pairs. This happens because squaring duplicates every prime factor in the original number. If 12 = 2² × 3, then 12² = 2⁴ × 3². To undo the square, take one factor from each identical pair.","The pairing is not decoration: each pair is one factor multiplied by itself. Taking the square root reverses that squaring, so one member of each pair remains."],board:["Prime-factor square-root method","1. Factorise the number completely into primes.","2. Put identical prime factors into pairs.","3. Take ONE factor from each complete pair.","4. Multiply the factors you took.","5. Square the result to check that it returns the original number."]},
{title:"7. Prime-factor method — no jump in the working",body:["We will not jump from the number straight to its root. Factorise, pair, select one from each pair, multiply, then check."],example:{q:"Find √144 using the prime-factor method.",steps:["Start by breaking 144 into prime factors.","144 ÷ 2 = 72, so write one factor 2.","72 ÷ 2 = 36, so write another factor 2.","36 ÷ 2 = 18, so write another factor 2.","18 ÷ 2 = 9, so write another factor 2.","9 ÷ 3 = 3, and 3 ÷ 3 = 1.","Therefore 144 = 2 × 2 × 2 × 2 × 3 × 3.","Group identical factors into pairs: (2 × 2) × (2 × 2) × (3 × 3).","Square root removes one copy from each pair, so take 2 × 2 × 3.","2 × 2 × 3 = 12.","Check: 12 × 12 = 144."],answer:"√144 = 12"},examples:[{q:"Find √196 by prime factors.",steps:["We want √196, so first rewrite 196 completely as prime factors. Start with the smallest prime that divides it, 2.","196÷2=98, so keep one factor 2. Since 98 is still even, divide by 2 again: 98÷2=49.","49 is not divisible by 2 or 3, but it is divisible by 7: 49=7×7. Therefore 196=2×2×7×7.","Now group identical factors into pairs: (2×2)(7×7). Each pair represents a square.","A square root takes one factor from each identical pair, so take one 2 and one 7.","Multiply the selected factors: 2×7=14.","Check by reversing the operation: 14²=14×14=196. Therefore √196=14."],answer:"√196 = 14"},{q:"Find √576 by prime factors.",steps:["576 = 2×2×2×2×2×2×3×3.","Pair them: (2×2)(2×2)(2×2)(3×3).","Take one from each pair: 2×2×2×3 = 24.","Check: 24² = 576."],answer:"√576 = 24"}]},
{title:"8. A larger factor-method example",body:["The same method works when several different prime factors occur. Keep the factors arranged so the pairs are visually obvious."],example:{q:"Find √900 using prime factors.",steps:["900 = 9 × 100.","9 = 3 × 3 and 100 = 2 × 2 × 5 × 5.","So 900 = (2 × 2) × (3 × 3) × (5 × 5).","Take one factor from each pair: 2 × 3 × 5.","2 × 3 × 5 = 30.","Check: 30 × 30 = 900."],answer:"√900 = 30"}},
{title:"9. What if the number is not a perfect square?",body:["Not every number has a whole-number square root. For such a number, first find the perfect square immediately below it and the perfect square immediately above it.","Their roots tell us the two consecutive whole numbers between which the required square root lies. This is estimation, not pretending the root is exact."] ,example:{q:"Estimate the position of √50.",steps:["Look for perfect squares around 50.","7² = 49.","8² = 64.","Therefore 49 < 50 < 64.","Taking square roots preserves this positive order: 7 < √50 < 8.","Because 50 is only 1 greater than 49, √50 is only a little greater than 7.","So √50 is between 7 and 8; it is not exactly 7 because 7² is 49."],answer:"7 < √50 < 8"},examples:[{q:"Between which integers does √30 lie?",steps:["5²=25 and 6²=36.","25 < 30 < 36.","Therefore 5 < √30 < 6."],answer:"5 < √30 < 6"},{q:"Between which integers does √130 lie?",steps:["11²=121 and 12²=144.","121 < 130 < 144.","Therefore 11 < √130 < 12."],answer:"11 < √130 < 12"}]},
{title:"10. Estimation by testing a decimal",body:["When a decimal estimate is required, test sensible values by squaring them. Each test tells you whether to move the estimate upward or downward."],example:{q:"Estimate √70 to one decimal place.",steps:["8²=64 and 9²=81, so √70 lies between 8 and 9.","Test 8.3: 8.3² = 68.89, which is below 70.","Test 8.4: 8.4² = 70.56, which is above 70.","So √70 lies between 8.3 and 8.4.","70 is closer to 70.56 than to 68.89, so to one decimal place √70 ≈ 8.4."],answer:"√70 ≈ 8.4 to 1 decimal place"}},
{title:"11. Quantitative reasoning: recognise when a square root is needed",body:["A word problem may never say 'take the square root'. Decide from the relationship. If the area of a square is known and the side is unknown, area = side², so finding the side requires the square root."] ,example:{q:"A square classroom floor has area 324 m². Find the length of one side.",steps:["For a square, area = side × side.","Let the side be s metres. Then s² = 324.","To undo squaring, take the positive square root: s = √324.","18 × 18 = 324, so √324 = 18.","A length cannot be negative in this physical problem."],answer:"The side length is 18 m."},examples:[{q:"A square tile has area 441 cm². Find its side.",steps:["For a square, area = side².","side = √441.","21 × 21 = 441."],answer:"Side = 21 cm"},{q:"A square garden has side 16 m. Find its area.",steps:["Here the side is known, so square it rather than taking a square root.","Area = 16² = 16 × 16 = 256."],answer:"Area = 256 m²"}]},
{title:"12. Multi-step application",body:["Some problems require a square root first and another operation afterward. Do not stop when you have found an intermediate value."],example:{q:"A square field has area 625 m². A fence will go around it. Find the total fence length.",steps:["The field is square, so first find its side from the area.","side = √625 = 25 m because 25 × 25 = 625.","The question asks for fence around the field, which means perimeter.","Perimeter of a square = 4 × side.","Perimeter = 4 × 25 m = 100 m.","Check: four equal sides of 25 m total 100 m."],answer:"100 m of fencing is required."}},
{title:"13. How to choose a method",body:["For a familiar perfect square such as 81 or 144, inspection can be efficient if you can justify it.","When the question specifically asks for the factor method, show the prime factorisation and pairs even if you already know the root.","For a non-perfect square, bracket it between neighbouring perfect squares and estimate if required. For a word problem, first identify the mathematical relationship before choosing the operation."]},
{title:"14. Mastery reasoning",body:["A learner has mastered this topic when they can explain the difference between a square and a square root, identify perfect squares, calculate squares, obtain roots by factor method, estimate non-perfect roots and recognise square-root relationships inside unfamiliar problems.","Every final answer should be checked when practical: square a proposed root and see whether you return to the original number."] ,example:{q:"A learner says √196 = 98 because 196 ÷ 2 = 98. Explain and correct the error.",steps:["The learner has confused square root with halving.","Square root asks for a number which, multiplied by itself, gives 196.","13² = 169, so the root is greater than 13.","14² = 14 × 14 = 196.","Therefore √196 = 14.","Check: 14 × 14 = 196; but 98 × 98 is nowhere near 196."],answer:"√196 = 14"}}
],mistakes:["Do not read a² as a × 2. It means a × a.","Square root does not mean divide by 2.","In the prime-factor method, pair identical prime factors and take one factor from every complete pair.","Do not call a non-perfect square root a whole number merely because it lies near one.","When a word problem asks for perimeter after giving area, finding the side is only an intermediate step.","Always distinguish an exact equality (=) from an estimate (≈)."]},
"Fractions":{title:"Fractions, Ratios, Decimals and Percentages",objectives:["Explain a fraction as equal parts of a whole or quantity and identify numerator and denominator","Recognise equivalent fractions and simplify fractions without changing their value","Convert fractions to decimals, percentages and ratios and explain why each conversion works","Convert decimals, percentages and ratios back to fractions where the comparison is valid","Distinguish part-to-whole from part-to-part comparisons","Solve quantitative aptitude and everyday problems involving fractions, ratios, decimals and percentages"],sections:[
{title:"1. Foundation: what is a fraction?",body:["A fraction describes equal parts. If one whole object is divided into 4 equal parts and you take 3 parts, you have three quarters, written 3/4.","The bottom number is the denominator. It tells us how many equal parts make one whole. The top number is the numerator. It tells us how many of those equal parts we are considering.","The word equal is essential. If a shape is cut into four pieces of different sizes, one piece is not automatically one quarter of the whole."],example:{q:"A loaf is cut into 8 equal slices and Tola eats 3. What fraction of the loaf did Tola eat?",steps:["The whole loaf has been divided into 8 equal parts, so the denominator is 8.","Tola ate 3 of those equal parts, so the numerator is 3.","Place the number eaten over the total equal parts: 3/8.","The remaining part would be 5/8 because 3/8 + 5/8 = 8/8 = 1 whole."],answer:"Tola ate 3/8 of the loaf."}},
{title:"2. A fraction is also division",body:["The fraction bar means division. Therefore a/b means a ÷ b, provided b is not zero.","This connection is the bridge from fractions to decimals. We are not using a new unrelated trick when we divide the numerator by the denominator; we are carrying out the division already written in the fraction."],example:{q:"Explain why 3/4 can be written as 0.75.",steps:["3/4 means 3 ÷ 4.","Because 3 is smaller than 4, the answer will be less than 1.","Write 3 as 3.00 so the division can continue into decimal places.","4 goes into 30 seven times: 7 × 4 = 28, leaving 2.","Bring down the next 0: 20 ÷ 4 = 5.","Therefore 3 ÷ 4 = 0.75.","Check: 0.75 × 4 = 3, so the division is correct."],answer:"3/4 = 0.75"}},
{title:"3. Equivalent fractions: same amount, different names",body:["Equivalent fractions look different but represent the same value. Multiplying or dividing the numerator and denominator by the same non-zero number preserves the fraction because we are effectively multiplying or dividing by 1.","For example, 1/2 × 2/2 = 2/4. Since 2/2 = 1, the value has not changed."],example:{q:"Show that 6/8 and 3/4 are equivalent.",steps:["Look for a number that divides both 6 and 8 exactly.","Both are divisible by 2.","6 ÷ 2 = 3.","8 ÷ 2 = 4.","So 6/8 = 3/4.","Check using division: 6 ÷ 8 = 0.75 and 3 ÷ 4 = 0.75."],answer:"6/8 = 3/4"}},
{title:"4. Simplifying a fraction completely",body:["To simplify a fraction, divide numerator and denominator by a common factor. To reach simplest form in one step, divide by their Highest Common Factor (HCF).","Why does the value stay unchanged? Because numerator and denominator are divided by the same non-zero number. We are reducing the number of equal parts and the number selected in the same proportion; the fraction gets a simpler name but represents the same amount.","A fraction is in simplest form when numerator and denominator have no common factor greater than 1."],board:["To simplify a fraction","1. Look for a factor common to numerator and denominator.","2. Divide BOTH by that same factor.","3. For one-step simplification, use their HCF.","4. Check whether any common factor greater than 1 remains.","5. If none remains, the fraction is in simplest form."],example:{q:"Simplify 18/30 completely.",steps:["Find a common factor of 18 and 30. Their HCF is 6.","Divide the numerator by 6: 18 ÷ 6 = 3.","Divide the denominator by the same 6: 30 ÷ 6 = 5.","Therefore 18/30 = 3/5.","Check that 3 and 5 have no common factor greater than 1, so 3/5 is simplest."],answer:"18/30 = 3/5"}},
{title:"5. Fraction to decimal — terminating examples",body:["To convert a fraction to a decimal, divide numerator by denominator. Some divisions end after a finite number of decimal places; these are terminating decimals.","Do not guess the decimal from the appearance of the fraction. Perform the division or create an equivalent fraction with denominator 10, 100, 1000 and so on when convenient."],example:{q:"Convert 7/8 to a decimal.",steps:["The fraction bar means division, so calculate 7 ÷ 8.","7 is smaller than 8, so write 7.000 and place 0 before the decimal point in the answer.","70 ÷ 8 = 8 remainder 6, giving 0.8 so far.","Bring down 0: 60 ÷ 8 = 7 remainder 4, giving 0.87.","Bring down 0: 40 ÷ 8 = 5 exactly.","Therefore 7 ÷ 8 = 0.875.","Check: 0.875 × 8 = 7."],answer:"7/8 = 0.875"},examples:[{q:"Convert 3/5 to a decimal.",steps:["3/5 means 3 ÷ 5.","30 tenths ÷ 5 = 6 tenths.","Therefore 3/5 = 0.6."],answer:"0.6"},{q:"Convert 5/16 to a decimal.",steps:["5/16 means 5 ÷ 16.","500 ÷ 16 = 31 remainder 4, giving 0.31 so far.","40 ÷ 16 = 2 remainder 8; 80 ÷ 16 = 5.","Therefore 5/16 = 0.3125."],answer:"0.3125"}]},
{title:"6. Fraction to percentage — understand 'per hundred'",body:["Percent means 'per hundred' or 'out of 100'. Therefore 35% means 35/100.","To convert a fraction to a percentage, find how many hundredths represent the same value. Multiplying by 100% works because 100% represents one whole: 100/100 = 1, so the value is not being changed."],example:{q:"Convert 7/20 to a percentage.",steps:["We want an equivalent fraction with denominator 100.","Ask: 20 × what number = 100? The answer is 5.","Multiply numerator by the same number: 7 × 5 = 35.","So 7/20 = 35/100.","35 out of 100 means 35%.","Check using the general method: 7/20 × 100% = 35%."],answer:"7/20 = 35%"},examples:[{q:"Convert 3/8 to a percentage.",steps:["Percent means out of 100, so we want to know how many hundredths have the same value as 3/8.","Because 8 does not multiply by a whole number to make 100, use the general method: multiply the fraction by 100%.","Write (3÷8)×100%.","First calculate 3÷8=0.375.","Now multiply 0.375 by 100.","0.375×100=37.5.","Attach the percent sign because the result is now expressed per hundred.","Therefore 3/8=37.5%."],answer:"37.5%"},{q:"Convert 9/4 to a percentage.",steps:["An improper fraction can represent more than one whole.","9/4 × 100% = 225%.","A value greater than 100% is reasonable because 9/4 = 2.25 wholes."],answer:"225%"}]},
{title:"7. Percentage to fraction — reverse the meaning",body:["Because percent means out of 100, write the percentage number over 100, then simplify.","A percentage may be greater than 100. That simply represents more than one whole."],example:{q:"Convert 62.5% to a fraction in simplest form.",steps:["62.5% means 62.5/100.","Remove the decimal by multiplying numerator and denominator by 10: 625/1000.","Find the HCF of 625 and 1000, which is 125.","625 ÷ 125 = 5.","1000 ÷ 125 = 8.","Therefore 62.5% = 5/8.","Check: 5 ÷ 8 = 0.625, and 0.625 × 100% = 62.5%."],answer:"62.5% = 5/8"},examples:[{q:"Convert 45% to a fraction.",steps:["45% = 45/100.","Divide top and bottom by 5: 9/20."],answer:"9/20"},{q:"Convert 140% to a fraction.",steps:["140% = 140/100.","Divide by 20: 7/5.","The improper fraction is expected because 140% is more than one whole."],answer:"7/5"}]},
{title:"8. Decimal to fraction — place value tells the denominator",body:["A terminating decimal can be read as tenths, hundredths, thousandths and so on. That place value gives the denominator before simplification.","For example, 0.4 means four tenths, 0.37 means thirty-seven hundredths and 0.625 means six hundred twenty-five thousandths."],example:{q:"Convert 0.375 to a fraction in simplest form.",steps:["There are three digits after the decimal point, so 0.375 means 375 thousandths.","Write 0.375 = 375/1000.","Both numerator and denominator are divisible by 125.","375 ÷ 125 = 3.","1000 ÷ 125 = 8.","Therefore 0.375 = 3/8.","Check: 3 ÷ 8 = 0.375."],answer:"0.375 = 3/8"},examples:[{q:"Convert 0.06 to a fraction.",steps:["0.06 means 6 hundredths: 6/100.","Divide by 2: 3/50."],answer:"3/50"},{q:"Convert 1.25 to a fraction.",steps:["1.25 = 125/100.","Divide numerator and denominator by 25.","125÷25=5 and 100÷25=4."],answer:"5/4 or 1 1/4"}]},
{title:"9. Percentage and decimal — why the decimal point moves",body:["To change a decimal to a percentage, multiply by 100 because percentage asks how many hundredths the value contains. Multiplying by 100 shifts place values two positions to the left, which appears as the decimal point moving two places right.","To change a percentage to a decimal, divide by 100. Do not memorise 'move the point' without knowing that multiplication or division by 100 is the reason."],example:{q:"Convert 0.086 to a percentage, then convert 125% to a decimal.",steps:["For 0.086, multiply by 100: 0.086 × 100 = 8.6.","Attach the percent sign because the result is now expressed per hundred: 8.6%.","For 125%, remove the percent meaning by dividing by 100: 125 ÷ 100 = 1.25.","Notice that 125% is greater than 100%, so its decimal 1.25 is greater than 1. This is reasonable."],answer:"0.086 = 8.6%; 125% = 1.25"}},
{title:"10. Ratio: what exactly is being compared?",body:["A ratio compares quantities. The order matters: 2:5 means first quantity to second quantity is 2 to 5.","A fraction often describes part of a whole, while a ratio may compare part to part or part to whole. Therefore we must read the words before converting.","If boys:girls = 2:3, then boys/girls = 2/3, but the fraction of the whole class who are boys is 2/(2+3) = 2/5. These are different questions."],example:{q:"A class has boys:girls = 3:5. What fraction of the whole class are boys?",steps:["The ratio says 3 equal parts are boys and 5 equal parts are girls.","The whole class therefore contains 3 + 5 = 8 equal ratio parts.","Boys occupy 3 of those 8 total parts.","So the fraction of the whole class who are boys is 3/8.","Do not answer 3/5: that compares boys directly with girls, not boys with the whole class."],answer:"Boys are 3/8 of the class."}},
{title:"11. Fraction to ratio — state the comparison",body:["A fraction a/b can be written numerically as a:b when it is explicitly comparing the first quantity with the second quantity. But context determines whether b is another part or the whole.","When a fraction describes 'part of a whole', a useful part-to-part ratio may require finding the remaining part first."],example:{q:"3/7 of a group are prefects. Find the ratio of prefects to non-prefects.",steps:["The whole group is represented by 7 equal parts.","Prefects occupy 3 parts.","Non-prefects occupy the remaining 7 − 3 = 4 parts.","Therefore prefects : non-prefects = 3 : 4.","Notice that 3:7 would be prefects : whole group, not prefects : non-prefects."],answer:"3:4"}},
{title:"12. Ratio to fraction and percentage of a whole",body:["When a ratio gives two or more parts of one whole, add the ratio parts first to find the total number of equal shares. Then place the required part over that total.","Once the fraction of the whole is known, the same quantity can be converted to a decimal or percentage."],example:{q:"Red:blue counters = 2:3. What percentage of all the counters are blue?",steps:["Red uses 2 ratio parts and blue uses 3 ratio parts.","Total parts = 2 + 3 = 5.","Blue therefore represents 3/5 of the whole.","Convert 3/5 to a decimal: 3 ÷ 5 = 0.6.","Convert to percentage: 0.6 × 100% = 60%."],answer:"60% of the counters are blue."}},
{title:"13. Sharing a quantity in a ratio",body:["To share a total in a ratio, add the ratio terms to find the number of equal shares. Divide the total by that number to find the value of one share, then multiply by each ratio term.","Always check that the final shares add back to the original total."],example:{q:"Share ₦4,200 in the ratio 2:5.",steps:["Add the ratio parts: 2 + 5 = 7 parts.","The ₦4,200 is divided into 7 equal shares.","Value of one share = ₦4,200 ÷ 7 = ₦600.","First share = 2 × ₦600 = ₦1,200.","Second share = 5 × ₦600 = ₦3,000.","Check: ₦1,200 + ₦3,000 = ₦4,200, the original total."],answer:"₦1,200 and ₦3,000"},examples:[{q:"Share 96 in the ratio 5:3.",steps:["The ratio 5:3 means the whole quantity is divided into 5+3 equal ratio-parts.","Add the ratio numbers: 5+3=8 parts altogether.","The total quantity is 96, so find the value of one ratio-part: 96÷8=12.","The first share has 5 parts, so 5×12=60.","The second share has 3 parts, so 3×12=36.","Check both conditions: 60+36=96, and 60:36 simplifies to 5:3."],answer:"60 and 36"},{q:"Share ₦18,000 in the ratio 2:3:4.",steps:["Total parts = 2+3+4=9.","One part = ₦18,000÷9=₦2,000.","Shares are ₦4,000, ₦6,000 and ₦8,000.","Check total = ₦18,000."],answer:"₦4,000, ₦6,000 and ₦8,000"}]},
{title:"14. Finding a percentage of a quantity",body:["A percentage is a fraction of 100, so p% of a quantity means p/100 multiplied by that quantity.","The word 'of' signals multiplication here. Simplify before multiplying when that makes the arithmetic clearer."],example:{q:"Find 35% of 240.",steps:["35% means 35/100.","So 35% of 240 = 35/100 × 240.","Simplify 240/100 to 12/5, or divide 240 by 100 first: 240 ÷ 100 = 2.4.","2.4 × 35 = 84.","Alternative check: 30% of 240 = 72 and 5% = 12; 72 + 12 = 84."],answer:"35% of 240 = 84"},examples:[{q:"Find 12.5% of 320.",steps:["12.5% means 12.5 out of 100.","Write 12.5/100 and simplify: multiply top and bottom by 10 to get 125/1000.","125/1000 simplifies to 1/8.","So finding 12.5% of 320 is the same as finding 1/8 of 320.","Divide 320 into 8 equal parts: 320÷8=40.","Therefore 12.5% of 320=40."],answer:"40"},{q:"Find 7.5% of ₦48,000.",steps:["7.5%=7.5/100=0.075.","0.075×48,000=3,600."],answer:"₦3,600"}]},
{title:"15. Finding the whole when a fraction or percentage is known",body:["Sometimes the problem gives a part and asks for the whole. Do not multiply by the percentage again. Build an equation showing that the stated fraction or percentage of the whole equals the known part.","This reverse reasoning is important in quantitative aptitude."],example:{q:"30% of a number is 24. Find the number.",steps:["Let the whole number be x.","30% means 30/100 = 0.30.","The statement becomes 0.30 × x = 24.","To undo multiplication by 0.30, divide both sides by 0.30.","x = 24 ÷ 0.30 = 80.","Check: 30% of 80 = 0.30 × 80 = 24."],answer:"The number is 80."},examples:[{q:"15% of a number is 54. Find the number.",steps:["Let the number be x.","0.15x=54.","x=54÷0.15=360.","Check: 15% of 360=54."],answer:"360"},{q:"3/7 of a quantity is 24. Find the whole quantity.",steps:["3/7 × x = 24.","One seventh is 24÷3=8.","Seven sevenths = 8×7=56."],answer:"56"}]},
{title:"16. Percentage increase and decrease",body:["A percentage change is measured against the original quantity unless the question states another base. First find the actual change, then compare that change with the original.","After finding a percentage increase or decrease, distinguish the amount of change from the new final value."],example:{q:"A quantity rises from 40 to 50. Find the percentage increase.",steps:["Original quantity = 40.","New quantity = 50.","Increase = 50 − 40 = 10.","Compare the increase with the original: 10/40.","Convert to percentage: 10/40 × 100% = 25%.","Check: 25% of 40 = 10, and 40 + 10 = 50."],answer:"The percentage increase is 25%."},examples:[{q:"A price falls from ₦8,000 to ₦6,800. Find the percentage decrease.",steps:["Decrease = ₦8,000−₦6,800=₦1,200.","Compare with the original price: 1,200/8,000×100%.","=15%."],answer:"15% decrease"},{q:"Increase ₦12,000 by 18%.",steps:["18% of ₦12,000 = ₦2,160.","New amount = ₦12,000+₦2,160.","Alternatively multiply by 1.18."],answer:"₦14,160"},{q:"Decrease 450 by 12%.",steps:["12% of 450=54.","New value=450−54=396.","Equivalent multiplier: 0.88×450=396."],answer:"396"},{q:"After a 20% increase, a price is ₦9,600. Find the original price.",steps:["After a 20% increase, the new price is 120% of the original.","Let original=x: 1.20x=9,600.","x=9,600÷1.20=8,000."],answer:"₦8,000"},{q:"A value increases by 20% and then decreases by 20%. Does it return to its original value?",steps:["Use 100 as an easy original value.","Increase 20%: 100→120.","Decrease 20% of the new 120: 20%×120=24.","120−24=96.","The two percentages use different bases, so they do not cancel."],answer:"No. It ends at 96, which is 4% below the original."}]},
{title:"17. Mixed quantitative reasoning — choose the representation that helps",body:["Fractions, ratios, decimals and percentages are not four disconnected topics. They are different ways to express relationships. In a problem, convert to the form that makes the required reasoning clearest.","Before calculating, ask: What is the whole? What is the part? What two quantities are being compared? Is the question asking for a share, a percentage, a decimal or a ratio?"],example:{q:"In a club of 80 learners, 3/8 are in the science group. Of the remaining learners, boys:girls = 2:3. How many girls are among the remaining learners?",steps:["First find the science group: 3/8 of 80.","80 ÷ 8 = 10, then 10 × 3 = 30 learners in the science group.","Remaining learners = 80 − 30 = 50.","Among the remaining learners, boys:girls = 2:3.","Total ratio parts = 2 + 3 = 5.","One ratio part = 50 ÷ 5 = 10.","Girls occupy 3 parts, so girls = 3 × 10 = 30.","Check: boys would be 20; 20 + 30 = 50 remaining learners."],answer:"30 girls"}},
{title:"18. Mastery: prove that the forms agree",body:["A strong learner should be able to travel in both directions: fraction ↔ decimal, fraction ↔ percentage, percentage ↔ decimal, and ratio ↔ fraction when the comparison is clearly defined.","Do not accept an answer merely because it looks familiar. Verify it by converting through another representation or checking against the original quantities."],example:{q:"A learner says 3/5 = 0.6 = 6% = 3:5. Identify the error and correct the chain.",steps:["Check the fraction-to-decimal step: 3 ÷ 5 = 0.6, so that part is correct.","Convert 0.6 to a percentage by multiplying by 100: 0.6 × 100% = 60%.","Therefore 6% is wrong; 6% would equal 0.06.","For a direct first-to-second numerical comparison, 3/5 corresponds to 3:5.","The corrected chain is 3/5 = 0.6 = 60%, with 3:5 representing the stated first-to-second ratio."],answer:"Corrected: 3/5 = 0.6 = 60%; direct ratio 3:5."}}
],mistakes:["Do not treat unequal pieces as fractions of equal size.","Do not change only the numerator or only the denominator when making an equivalent fraction.","The fraction bar means division; do not invent a decimal from the digits.","Percent means per hundred. 0.6 is 60%, not 6%.","Always simplify a fraction when simplest form is required.","A part-to-part ratio such as boys:girls = 3:5 does not mean boys are 3/5 of the whole class; the whole has 8 ratio parts.","When sharing in a ratio, add the ratio parts before dividing the total.","Percentage change is normally compared with the original quantity, not the new quantity.","Distinguish the amount of a percentage change from the final amount after the change.","Check conversions by moving through another form or substituting back into the original problem."]},
"Commercial Arithmetic":{title:"Commercial Arithmetic",objectives:["Use arithmetic confidently in household, office and market situations","Interpret bills, receipts, budgets and simple financial records","Distinguish cost price, selling price, marked price, profit and loss","Calculate profit and loss amounts and percentages","Calculate discounts and final prices in direct and reverse problems","Calculate simple interest, principal, rate, time and total amount","Calculate commission and solve multi-step commercial problems"],sections:[
{title:"1. Why commercial arithmetic matters",body:["Commercial arithmetic is ordinary mathematics applied to money decisions in homes, offices and markets. The difficulty is often not multiplication itself but deciding what each number means and which quantity is the correct base.","Before calculating, identify the quantities, their units and the question being asked. Money answers should carry the correct currency symbol and should be checked for reasonableness."],examples:[{q:"A family receives ₦185,000 in a month and plans expenses of ₦42,000, ₦55,000, ₦28,000 and ₦36,000. Find the balance.",steps:["Total planned expenditure = 42,000+55,000+28,000+36,000 = ₦161,000.","Balance = income−expenditure = ₦185,000−₦161,000 = ₦24,000.","Because expenditure is below income, this is a surplus, not a deficit."],answer:"Balance = ₦24,000 surplus"},{q:"An office has ₦96,500 available but its planned expenses total ₦104,200. Find the deficit.",steps:["Deficit means planned expenditure exceeds available money.","Deficit = ₦104,200−₦96,500 = ₦7,700."],answer:"Deficit = ₦7,700"}]},
{title:"2. Bills and household arithmetic",body:["A bill records amounts owed for goods or services. Some bills use quantity × unit price; others combine fixed charges and usage charges. Read the structure before adding.","Always distinguish a subtotal from the final total when another charge or reduction still has to be applied."],examples:[{q:"A household buys 6 units of an item at ₦1,250 each and 4 units at ₦850 each. Find the total bill.",steps:["First item: 6×₦1,250=₦7,500.","Second item: 4×₦850=₦3,400.","Total bill=₦7,500+₦3,400=₦10,900."],answer:"₦10,900"},{q:"An electricity bill has a fixed charge of ₦1,500 plus ₦68 for each of 120 units used. Find the bill.",steps:["Usage charge=120×₦68=₦8,160.","Add fixed charge: ₦8,160+₦1,500=₦9,660."],answer:"₦9,660"}]},
{title:"3. Cost price, selling price, profit and loss",body:["Before using any formula, identify the two prices. Cost Price (CP) is what the trader paid for the article. Selling Price (SP) is what the trader receives when the article is sold.","Now compare them. If the selling price is greater, the trader received more than was spent, so the difference is profit. If the cost price is greater, the trader received less than was spent, so the difference is loss."],board:["If SP > CP:","Profit = Selling Price − Cost Price","Profit = SP − CP","","If CP > SP:","Loss = Cost Price − Selling Price","Loss = CP − SP"],examples:[{q:"A trader buys a bag for ₦24,000 and sells it for ₦30,000. Find the profit.",steps:["SP is greater than CP, so there is a profit.","Profit=SP−CP=₦30,000−₦24,000=₦6,000."],answer:"Profit = ₦6,000"},{q:"A phone bought for ₦85,000 is sold for ₦76,500. Find the loss.",steps:["CP is greater than SP, so there is a loss.","Loss=CP−SP=₦85,000−₦76,500=₦8,500."],answer:"Loss = ₦8,500"}]},
{title:"4. Profit and loss percentages — choose the correct base",body:["To find a profit percentage, we first need the actual profit. That is why Profit = SP − CP must already be established before the percentage formula is used.","Next ask: percentage of what? Profit or loss is compared with the Cost Price because CP is the original amount the trader invested. So the cost price becomes the denominator.","The same reasoning gives the loss-percentage formula. Do not divide by selling price unless a question explicitly defines a different comparison."],board:["Step 1: Find the gain or loss","Profit = SP − CP","Loss = CP − SP","","Step 2: Compare it with the original Cost Price","Profit % = (Profit ÷ CP) × 100%","Loss % = (Loss ÷ CP) × 100%"],examples:[{q:"An article costs ₦24,000 and sells for ₦30,000. Find profit percent.",steps:["First identify the prices: CP=₦24,000 and SP=₦30,000.","Because SP is greater than CP, this is a profit.","Find the profit before using a percentage: Profit=SP−CP.","Profit=₦30,000−₦24,000.","Profit=₦6,000.","Now compare that ₦6,000 profit with the original amount invested, the CP.","Profit %=(Profit÷CP)×100%.","Profit %=(₦6,000÷₦24,000)×100%.","₦6,000÷₦24,000=1/4.","1/4×100%=25%.","Check: 25% of ₦24,000 is ₦6,000, and ₦24,000+₦6,000=₦30,000."],answer:"25% profit"},{q:"A trader buys goods for ₦50,000 and sells them for ₦42,500. Find loss percent.",steps:["Identify the prices first: CP=₦50,000 and SP=₦42,500.","Because SP is below CP, money was lost rather than gained.","Find the loss amount before finding its percentage: Loss=CP−SP.","Loss=₦50,000−₦42,500.","Loss=₦7,500.","A loss percentage compares the loss with the original cost price, because CP is the amount originally invested.","Loss %=(Loss÷CP)×100%.","Loss %=(₦7,500÷₦50,000)×100%.","₦7,500÷₦50,000=0.15.","0.15×100%=15%.","Check: 15% of ₦50,000 is ₦7,500; subtracting it gives ₦42,500, the stated SP."],answer:"15% loss"},{q:"An item costs ₦8,400 and yields ₦1,260 profit. Find the profit percentage.",steps:["The profit amount is already given.","Profit%=1,260/8,400×100%.","1,260÷8,400=0.15."],answer:"15% profit"}]},
{title:"5. Finding selling price from a profit or loss percentage",body:["Start from the relationship already established: selling at a profit means the selling price is the cost price plus the profit. Selling at a loss means the selling price is the cost price minus the loss.","If the question gives a percentage rather than the naira profit or loss, first find that percentage of CP. Only after the learner understands this should the shorter percentage multiplier be introduced."],board:["At a profit:","Profit = (profit rate ÷ 100) × CP","SP = CP + Profit","","At a loss:","Loss = (loss rate ÷ 100) × CP","SP = CP − Loss","","Shortcut after understanding:","SP at p% profit = ((100 + p) ÷ 100) × CP","SP at p% loss = ((100 − p) ÷ 100) × CP"],examples:[{q:"A bicycle costs ₦64,000. Find the selling price for a 25% profit.",steps:["The cost price is ₦64,000. A 25% profit means the profit itself is 25% of that cost price.","Find the profit first: Profit=(25÷100)×₦64,000.","Profit=0.25×₦64,000.","Profit=₦16,000.","Selling at a profit means add the profit to the cost price.","SP=CP+Profit.","SP=₦64,000+₦16,000.","SP=₦80,000.","Only after understanding this can we use the shortcut: 100%+25%=125% of CP."],answer:"₦80,000"},{q:"A machine costs ₦150,000 and is sold at 12% loss. Find SP.",steps:["Loss=12% of ₦150,000=₦18,000.","SP=₦150,000−₦18,000=₦132,000.","Check using 88% of CP: 0.88×150,000=132,000."],answer:"₦132,000"}]},
{title:"6. Reverse profit and loss problems",body:["If selling price is known after a percentage profit or loss, the selling price represents a percentage of the original cost price. Do not simply subtract the stated percentage from SP.","At 20% profit, SP=120% of CP. At 15% loss, SP=85% of CP."],examples:[{q:"An item is sold for ₦72,000 at 20% profit. Find its cost price.",steps:["The unknown is CP, so do not begin by subtracting 20% from the selling price. The 20% profit is based on CP.","CP itself represents 100% of CP. Adding a 20% profit makes the selling price 100%+20%=120% of CP.","Therefore SP=120% of CP.","Convert 120% to decimal form: 120÷100=1.20.","Substitute the known selling price: ₦72,000=1.20×CP.","To get CP alone, divide both sides by 1.20.","CP=₦72,000÷1.20.","CP=₦60,000.","Check: 20% of ₦60,000=₦12,000 and ₦60,000+₦12,000=₦72,000."],answer:"CP = ₦60,000"},{q:"An item is sold for ₦51,000 at a 15% loss. Find CP.",steps:["At 15% loss, SP=85% of CP.","0.85×CP=₦51,000.","CP=₦51,000÷0.85=₦60,000.","Check: 15% of 60,000=9,000; 60,000−9,000=51,000."],answer:"CP = ₦60,000"}]},
{title:"7. Marked price, discount and amount paid",body:["Marked Price (MP) is the price written on the item before any reduction. Discount is the amount removed from that marked price. The amount the customer finally pays is therefore what remains after the discount is removed.","When a discount rate is given, calculate the discount from the marked price first. This makes the meaning clear before introducing any shortcut."],board:["Discount = Marked Price − Selling Price","Selling Price = Marked Price − Discount","","Discount % = (Discount ÷ Marked Price) × 100%","","If discount rate is given:","Discount = (rate ÷ 100) × Marked Price"],examples:[{q:"A ₦40,000 item has a 15% discount. Find the discount and amount paid.",steps:["Discount=15/100×₦40,000=₦6,000.","Amount paid=₦40,000−₦6,000=₦34,000."],answer:"Discount ₦6,000; amount paid ₦34,000"},{q:"A shirt marked ₦18,000 is sold for ₦15,300. Find the discount percentage.",steps:["Discount=₦18,000−₦15,300=₦2,700.","Discount%=2,700/18,000×100%=15%."],answer:"15% discount"},{q:"After a 20% discount, a customer pays ₦28,000. Find the marked price.",steps:["After 20% discount, the customer pays 80% of MP.","0.80×MP=₦28,000.","MP=₦28,000÷0.80=₦35,000."],answer:"Marked price = ₦35,000"}]},
{title:"8. Simple interest — understand the quantities",body:["Establish every quantity before using the formula. Principal (P) is the original amount borrowed or invested. Rate (R) tells the percentage interest for each stated time period. Time (T) tells how many of those periods the money remains borrowed or invested.","For simple interest, each year's interest is calculated on the same original principal. One year's interest is R% of P. For T years, that yearly interest is repeated T times. This is what produces the compact formula below."],board:["Interest for 1 year = (R ÷ 100) × P","Interest for T years = (R ÷ 100) × P × T","","Therefore:","I = (P × R × T) ÷ 100","","Total Amount = Principal + Interest","A = P + I"],examples:[{q:"Find simple interest on ₦50,000 at 8% per annum for 3 years.",steps:["Identify what each number represents before substituting: Principal P=₦50,000, annual Rate R=8%, and Time T=3 years.","Because the rate is per annum and the time is already in years, no time conversion is needed.","One year’s interest is 8% of ₦50,000.","Interest for 3 years is therefore that same simple-interest amount repeated for 3 years.","Use I=(P×R×T)÷100.","I=(50,000×8×3)÷100.","50,000×8×3=1,200,000.","1,200,000÷100=₦12,000.","The question also requires the amount, so add the original principal: A=P+I.","A=₦50,000+₦12,000.","A=₦62,000."],answer:"Interest ₦12,000; amount ₦62,000"},{q:"Find the simple interest on ₦120,000 at 7.5% per annum for 2 years.",steps:["I=120,000×7.5×2/100.","7.5×2=15, so this is 15% of ₦120,000.","I=₦18,000."],answer:"₦18,000"}]},
{title:"9. Time conversions in simple interest",body:["The time unit must agree with the rate. If the rate is per annum and time is given in months, convert months to years before substitution.","12 months=1 year, so m months=m/12 years."],examples:[{q:"Find simple interest on ₦80,000 at 9% per annum for 8 months.",steps:["Convert time: 8 months=8/12 year=2/3 year.","I=80,000×9×(2/3)/100.","9×2/3=6.","I=6% of ₦80,000=₦4,800."],answer:"₦4,800"},{q:"Find interest on ₦36,000 at 10% per annum for 18 months.",steps:["18 months=18/12=1.5 years.","I=36,000×10×1.5/100.","10×1.5=15%, so I=15% of 36,000."],answer:"₦5,400"}]},
{title:"10. Reverse simple-interest problems",body:["The same formula can be rearranged when principal, rate or time is unknown. Keep the meaning visible rather than memorising several disconnected formulas.","From I=PRT/100: P=100I/(RT), R=100I/(PT), and T=100I/(PR)."],examples:[{q:"₦60,000 earns ₦9,000 simple interest in 3 years. Find the annual rate.",steps:["I=PRT/100.","9,000=60,000×R×3/100.","60,000×3/100=1,800, so 9,000=1,800R.","R=9,000÷1,800=5."],answer:"5% per annum"},{q:"At 6% simple interest, how long will ₦40,000 take to earn ₦7,200?",steps:["7,200=40,000×6×T/100.","40,000×6/100=2,400.","7,200=2,400T.","T=3 years."],answer:"3 years"}]},
{title:"11. Commission",body:["Commission is a payment earned for making sales or completing specified transactions. Before calculating, identify the sales value and the commission rate.","A rate of 5% means the salesperson receives 5 out of every 100 units of the sales value. That meaning gives the formula. If there is also a fixed salary, calculate commission separately and add it only when total earnings are requested."],board:["Commission = (Commission rate ÷ 100) × Total sales","","If fixed salary is also paid:","Total earnings = Fixed salary + Commission"],examples:[{q:"A salesperson earns 5% commission on ₦280,000 sales. Find commission.",steps:["Commission=5/100×₦280,000.","=0.05×₦280,000=₦14,000."],answer:"₦14,000"},{q:"A salesperson receives ₦45,000 salary plus 4% commission on ₦600,000 sales. Find total earnings.",steps:["Commission=4% of ₦600,000=₦24,000.","Total earnings=salary+commission=₦45,000+₦24,000."],answer:"₦69,000"},{q:"A salesperson earned ₦18,000 commission at 6%. Find the sales value.",steps:["0.06×sales=₦18,000.","sales=18,000÷0.06=₦300,000."],answer:"₦300,000"}]},
{title:"12. Multi-step commercial reasoning",body:["Real commercial questions often combine two or more ideas. Work in the order events occur and keep each base quantity clear.","A discount changes what the buyer pays; profit compares selling price with cost price. Those percentages may use different bases."],examples:[{q:"A trader buys an item for ₦48,000, marks it at ₦75,000 and gives a 20% discount. Find the actual selling price and profit percentage.",steps:["There are two different percentage bases here, so handle the events in order.","The discount is based on the marked price, ₦75,000.","Discount=(20÷100)×₦75,000.","Discount=₦15,000.","Subtract the discount from the marked price to obtain the actual selling price.","Actual SP=₦75,000−₦15,000.","Actual SP=₦60,000.","Now compare this selling price with the trader’s cost price of ₦48,000.","Profit=SP−CP=₦60,000−₦48,000.","Profit=₦12,000.","Profit percentage is based on CP, not marked price.","Profit %=(₦12,000÷₦48,000)×100%.","Profit %=25%."],answer:"SP ₦60,000; profit 25%"},{q:"A trader wants 20% profit after giving a 10% discount. If CP=₦45,000, what marked price is needed?",steps:["Required SP for 20% profit=120% of ₦45,000=₦54,000.","A 10% discount means actual SP is 90% of marked price.","0.90×MP=₦54,000.","MP=₦54,000÷0.90=₦60,000.","Check: 10% discount on 60,000 is 6,000, leaving 54,000."],answer:"Marked price = ₦60,000"}]},
{title:"13. Mastery and reasonableness checks",body:["Before accepting an answer, ask whether its direction makes sense: a discounted price should be below marked price; a selling price at a profit should be above cost price; a loss selling price should be below cost price; interest should reflect principal, rate and time.","A learner is ready when the unknown can move position—profit, CP, SP, rate, time, discount, marked price or commission—and the learner can reconstruct the relationship instead of depending on one memorised question form."]}],mistakes:["Do not calculate profit or loss before identifying CP and SP.","Profit/loss percentage normally uses cost price as its base.","Discount percentage uses marked price as its base.","Discount is the reduction, not the final amount paid.","A reverse percentage problem cannot usually be solved by simply subtracting the percentage from the final value.","For simple interest, make the time unit agree with the rate.","Amount in simple interest means principal plus interest.","Commission may need to be added to fixed salary when total earnings are requested.","In multi-step questions, identify which percentage applies to which base before calculating."]},
"Approximation":{title:"Approximation",objectives:["Explain approximation and distinguish an exact value from an approximate value","Round whole numbers and decimals to a stated place value or number of decimal places","Round numbers to a stated number of significant figures","Handle zeros and carrying correctly when rounding","Choose a suitable degree of accuracy from context","Estimate calculations and use approximation to check reasonableness","Solve quantitative aptitude problems involving decimal places and significant figures"],sections:[
{title:"1. Exact and approximate values",body:["An exact value is stated without deliberate rounding. An approximate value is close to the exact value but has been rounded or estimated to a chosen degree of accuracy.","The symbol = means exactly equal. The symbol ≈ means approximately equal. Approximation is useful when an exact value is unnecessary, unavailable or inconvenient."],examples:[{q:"A calculator gives 17.8462. Write this approximately to one decimal place.",steps:["One decimal place means keep the tenths digit.","In 17.8462, the tenths digit is 8.","The next digit, the hundredths digit, is 4.","Because 4 is below 5, keep 8 unchanged."],answer:"17.8462 ≈ 17.8"},{q:"Explain why 1/3 = 0.333... but 1/3 ≈ 0.33 to 2 decimal places.",steps:["0.333... continues indefinitely, so it represents the exact decimal value of 1/3.","0.33 stops after two decimal places.","Therefore 0.33 is a rounded approximation, not an exact equality."],answer:"Use ≈ for the rounded value: 1/3 ≈ 0.33"}]},
{title:"2. The rounding decision: keep one digit, inspect the next",body:["First locate the digit required by the question. That is the last digit you intend to keep. Then inspect the digit immediately to its right.","Why inspect that next digit? It tells us which neighbouring rounded value the original number is nearer to. Under the school convention, 0–4 leaves the retained digit at the lower choice, while 5–9 means the number has reached or passed halfway and the retained digit increases.","If the next digit is 0,1,2,3 or 4, the kept digit stays unchanged. If it is 5,6,7,8 or 9, increase the kept digit by 1. Digits after the rounding position are then removed or replaced by zeros when place value requires them."],board:["Every rounding question","1. Read the accuracy requested.","2. Locate the LAST digit that must remain.","3. Inspect the ONE digit immediately to its right.","4. 0–4: keep the retained digit unchanged.","5. 5–9: increase the retained digit by 1.","6. Remove later digits or replace them with place-value zeros.","7. Check that the answer is written to the requested accuracy."],examples:[{q:"Round 6,342 to the nearest hundred.",steps:["The question asks for the nearest hundred, so first locate the hundreds place. That is the last place allowed to remain exact.","The hundreds digit is 3. The digit immediately to its right is the tens digit, 4; this is the deciding digit.","Because 4 is below 5, the original number is closer to the lower hundred than the next hundred. Keep 3 unchanged.","Digits to the right no longer show exact tens or units, so replace them with zeros to preserve place value.","Read the final rounded number and check that it is a multiple of 100."],answer:"6,300"},{q:"Round 6,372 to the nearest hundred.",steps:["The hundreds digit is 3.","The next digit is 7.","7≥5, so increase 3 to 4.","Replace the remaining digits with zeros."],answer:"6,400"},{q:"Round 2,650 to the nearest hundred.",steps:["Keep the hundreds digit 6.","The tens digit is 5.","Using the school rounding convention, 5 rounds upward.","Increase 6 to 7 and replace the remaining places with zeros."],answer:"2,700"}]},
{title:"3. Rounding whole numbers to place value",body:["Questions may ask for the nearest ten, hundred, thousand or another place value. The same decision rule applies; what changes is the digit being kept.","Zeros after the rounded digit are important placeholders. 48,000 and 48 are completely different values."],examples:[{q:"Round 47,286 to the nearest ten.",steps:["The tens digit is 8.","Inspect the units digit 6.","6≥5, so 8 rounds to 9.","Replace the units digit with zero."],answer:"47,290"},{q:"Round 47,286 to the nearest thousand.",steps:["The thousands digit is 7.","Inspect the hundreds digit 2.","2<5, so keep 7.","Replace hundreds, tens and units with zeros."],answer:"47,000"},{q:"Round 685,499 to the nearest ten thousand.",steps:["The ten-thousands digit is 8.","Inspect the thousands digit 5.","5≥5, so increase 8 to 9.","Replace all following places with zeros."],answer:"690,000"}]},
{title:"4. Decimal places: count from the decimal point",body:["Decimal places (d.p.) count digits to the right of the decimal point. For 18.3764, 3 is the first decimal place, 7 the second, 6 the third and 4 the fourth.","Do not count digits before the decimal point when a question asks for decimal places."],examples:[{q:"Round 18.3764 to 2 decimal places.",steps:["Keep two digits after the decimal point: 18.37.","Inspect the third decimal digit: 6.","6≥5, so increase the second decimal digit 7 to 8."],answer:"18.38"},{q:"Round 5.2431 to 3 decimal places.",steps:["Keep 5.243.","Inspect the fourth decimal digit 1.","1<5, so 3 stays unchanged."],answer:"5.243"},{q:"Round 0.008764 to 4 decimal places.",steps:["Count four places after the decimal: 0.0087.","The next digit is 6.","Increase the fourth decimal digit 7 to 8."],answer:"0.0088"}]},
{title:"5. Decimal rounding when carrying occurs",body:["Sometimes rounding a 9 upward creates 10. Then the extra 1 must carry into the digit to the left, just as in ordinary addition.","This may cross the decimal point and can even change the whole-number part."],examples:[{q:"Round 7.996 to 2 decimal places.",steps:["Keep 7.99 initially.","The next digit is 6, so the hundredths 9 must increase.","9+1=10, so write 0 and carry 1 to the tenths 9.","That 9 also becomes 10, so carry 1 to the units digit 7."],answer:"8.00"},{q:"Round 19.9952 to 2 decimal places.",steps:["Keep 19.99.","The next digit is 5, so round upward.","The two 9s carry through into the whole-number part.","Because the answer is required to 2 d.p., retain two decimal-place zeros."],answer:"20.00"}]},
{title:"6. What significant figures mean",body:["Significant figures (s.f.) count meaningful digits beginning with the first non-zero digit. This is different from decimal places, which begin immediately after the decimal point.","Leading zeros only locate the decimal point and are not significant. Zeros between non-zero digits are significant. Trailing zeros may be significant when the stated accuracy makes them part of the rounded value."],examples:[{q:"Identify the first three significant digits in 0.004072.",steps:["Ignore leading zeros before 4.","The first significant digit is 4.","The zero between 4 and 7 is significant, so it is the second.","7 is the third significant digit."],answer:"The first three significant digits are 4, 0, 7"},{q:"How many significant figures are shown in 5.060?",steps:["5 is significant.","The zero between 5 and 6 is significant.","6 is significant.","The final zero after the decimal is written to show precision, so it is significant."],answer:"5.060 shows 4 significant figures"}]},
{title:"7. Rounding decimals to significant figures",body:["Locate the first non-zero digit, count the required number of significant digits from there, then inspect the next digit.","A small number may have many decimal places but only a few significant figures because its leading zeros do not count."],examples:[{q:"Round 0.006482 to 2 significant figures.",steps:["Ignore the leading zeros.","The first significant digit is 6 and the second is 4.","The next digit is 8, so round 4 upward to 5.","Keep the decimal position unchanged."],answer:"0.0065"},{q:"Round 0.040759 to 3 significant figures.",steps:["The first non-zero digit is 4.","Count 4,0,7 as the first three significant digits.","The next digit is 5, so 7 rounds to 8."],answer:"0.0408"},{q:"Round 3.14159 to 4 significant figures.",steps:["The first four significant digits are 3,1,4,1.","The next digit is 5.","Increase the fourth significant digit from 1 to 2."],answer:"3.142"}]},
{title:"8. Rounding large numbers to significant figures",body:["For large whole numbers, count significant figures from the first non-zero digit on the left. After rounding, replace unused place-value positions with zeros.","Those zeros preserve the size of the number even when they are not counted as additional significant figures in the stated approximation."],examples:[{q:"Round 53,782 to 2 significant figures.",steps:["The first two significant digits are 5 and 3.","The next digit is 7, so 3 rounds to 4.","The remaining positions become zeros."],answer:"54,000"},{q:"Round 704,621 to 3 significant figures.",steps:["The first three significant digits are 7,0,4.","The next digit is 6, so increase 4 to 5.","Replace the remaining digits with zeros."],answer:"705,000"},{q:"Round 9,965,000 to 3 significant figures.",steps:["The first three significant digits are 9,9,6.","The next digit is 5, so 6 rounds to 7.","Retain the correct million-scale place values."],answer:"9,970,000"}]},
{title:"9. Decimal places versus significant figures",body:["The same number can produce different answers depending on whether the instruction says decimal places or significant figures. Always read the requested accuracy before rounding.","For numbers below 1, this distinction is especially important because leading zeros count as decimal places but not as significant figures."],examples:[{q:"Round 0.004786 to 3 decimal places and to 3 significant figures.",steps:["For 3 d.p., keep three digits after the decimal: 0.004. The next digit is 7, so round the third decimal digit 4 to 5: 0.005.","For 3 s.f., ignore leading zeros and count 4,7,8. The next digit is 6, so 8 rounds to 9.","The two instructions measure accuracy differently."],answer:"3 d.p.: 0.005; 3 s.f.: 0.00479"},{q:"Round 12.468 to 2 d.p. and 2 s.f.",steps:["For 2 decimal places, count two digits to the right of the decimal point. The last retained digit is 6 in 12.46.","Inspect the next digit, 8. Since 8≥5, increase 6 to 7. This gives 12.47.","Now start again from the original number for 2 significant figures.","Significant figures begin at the first non-zero digit. In 12.468, the first two significant digits are 1 and 2.","Inspect the next significant digit, 4. Since 4<5, keep the 2 unchanged.","Digits after the retained units digit are removed, so the 2-s.f. value is 12.","The two answers differ because decimal places and significant figures measure accuracy in different ways."],answer:"2 d.p.: 12.47; 2 s.f.: 12"}]},
{title:"10. Choosing a sensible degree of accuracy",body:["The required accuracy should suit the context. Reporting a classroom length measured with an ordinary tape to ten decimal places would suggest a precision the measurement does not have.","When a question explicitly states the required accuracy, follow it. When it does not, consider the measuring instrument and purpose."],examples:[{q:"A road distance is measured as 12,684 m. Express it to the nearest kilometre.",steps:["1 km=1,000 m.","12,684 m=12.684 km.","To the nearest kilometre, inspect the tenths digit 6.","6≥5, so 12 km rounds to 13 km."],answer:"13 km"},{q:"A mass is 4.376 kg. Give it to the nearest 0.1 kg.",steps:["Nearest 0.1 kg means one decimal place.","Keep 4.3 and inspect the hundredths digit 7.","Round the tenths digit upward."],answer:"4.4 kg"}]},
{title:"11. Estimating calculations",body:["Approximation can make a difficult calculation quick enough to perform mentally. Round each number to convenient values, calculate the estimate, and clearly label it as an estimate.","An estimate is especially useful before an exact calculation because it provides a benchmark for detecting calculator or transcription errors."],examples:[{q:"Estimate 49.8 × 19.7.",steps:["Round 49.8≈50 and 19.7≈20.","50×20=1,000.","Because both rounded values are close to the originals, 1,000 is a sensible estimate."],answer:"Approximately 1,000"},{q:"Estimate 598 ÷ 19.8.",steps:["Use convenient nearby values: 598≈600 and 19.8≈20.","600÷20=30."],answer:"Approximately 30"},{q:"Estimate (31.2×4.9)/10.1.",steps:["Round to convenient values: 31.2≈30, 4.9≈5, 10.1≈10.","30×5=150.","150÷10=15."],answer:"Approximately 15"}]},
{title:"12. Using estimation to check an answer",body:["If an exact calculation is very far from a sensible estimate, investigate before accepting it. The estimate does not prove the exact answer, but it can expose misplaced decimal points and unreasonable calculator entries.","Compare orders of magnitude as well as the digits."],examples:[{q:"A learner calculates 39.7×5.1=2,024.7. Use approximation to assess the answer.",steps:["39.7≈40 and 5.1≈5.","40×5=200.","An exact answer should be near 200, not near 2,000.","The learner's answer is therefore unreasonable.","Indeed, 39.7×5.1=202.47."],answer:"2,024.7 is unreasonable; the correct value is 202.47"},{q:"A calculator entry gives 802÷3.98=20.15. Is this reasonable?",steps:["802≈800 and 3.98≈4.","800÷4=200.","20.15 is about ten times too small, so it is not reasonable."],answer:"No; the answer should be around 200"}]},
{title:"13. Quantitative aptitude: work backwards from a rounded value",body:["A rounded answer represents a range of possible original values. For whole-number rounding, values up to halfway below and halfway above the rounded value belong to that rounding interval, with the upper endpoint excluded under the usual convention.","This reasoning tests whether the learner understands approximation rather than merely performing it."],examples:[{q:"A whole number rounds to 3,500 to the nearest hundred. Give the smallest and largest possible whole numbers.",steps:["Half of 100 is 50.","Numbers from 3,450 round up to 3,500.","The next boundary is 3,550, which rounds to 3,600.","Therefore the largest whole number still rounding to 3,500 is 3,549."],answer:"Smallest 3,450; largest 3,549"},{q:"A measurement rounds to 7.4 cm to the nearest 0.1 cm. Describe its possible range.",steps:["Half of 0.1 is 0.05.","Lower boundary=7.4−0.05=7.35.","Upper boundary=7.4+0.05=7.45.","7.45 itself would round to 7.5 under the usual convention, so the upper boundary is not included."],answer:"7.35 cm ≤ value < 7.45 cm"}]},
{title:"14. Mixed approximation reasoning",body:["Exam questions may combine place value, decimal places, significant figures and estimation. First identify what the instruction measures, then apply the correct method.","A strong learner should also be able to explain why two different stated accuracies produce different approximations of the same number."],examples:[{q:"A population is recorded as 486,739. Give it to the nearest thousand and to 2 significant figures.",steps:["Nearest thousand: keep 486 thousand and inspect 739; the hundreds digit is 7, so round to 487,000.","For 2 s.f., keep 4 and 8; the next digit is 6, so 48 rounds to 49.","Restore place value: 490,000."],answer:"Nearest thousand: 487,000; 2 s.f.: 490,000"},{q:"A learner says 0.00795 to 2 s.f. is 0.0079. Correct the reasoning.",steps:["Ignore leading zeros; significant digits begin at 7.","The first two significant digits are 7 and 9.","The next digit is 5, so the second significant digit must round upward.","Rounding 9 upward causes carrying: 79 becomes 80 at this place."],answer:"0.00795 ≈ 0.0080 to 2 significant figures"}]},
{title:"15. Mastery standard",body:["You have mastered approximation when you can identify the required accuracy, locate the correct rounding digit, handle zeros and carrying, distinguish decimal places from significant figures, estimate calculations, judge reasonableness and solve reverse or mixed approximation problems.","Do not treat the rule '5 or more, round up' as the whole topic. The real skill is knowing which digit is being kept, what its place value means, and whether the resulting approximation makes sense."]}],mistakes:["Do not confuse an exact equality (=) with an approximation (≈).","For decimal places, count from the decimal point; for significant figures, begin at the first non-zero digit.","Leading zeros are not significant figures.","Zeros between non-zero digits are significant.","When rounding a whole number, preserve its place value with zeros.","If a 9 rounds upward, carry correctly into the digit to the left.","Do not give an estimate as though it were an exact answer.","When checking a calculation, an answer far from a sensible estimate should be investigated.","Always read whether the question asks for a place value, decimal places or significant figures before rounding."]},
"Multiplication and Division of Directed Numbers":{title:"Multiplication and Division of Directed Numbers",objectives:["Explain directed numbers as quantities with both size and direction","Interpret positive and negative values in practical situations","Derive and use the sign rules for multiplication of directed numbers","Derive and use the sign rules for division of directed numbers","Evaluate expressions containing several directed-number factors or quotients","Use square and square-root tables correctly and check table values for reasonableness","Interpret mathematical information in tables, charts, records and schedules","Solve quantitative and real-life problems involving directed numbers"],sections:[
{title:"1. Foundation: a number can tell us size and direction",body:["A directed number has two pieces of information: its numerical size and its direction from zero. The + or − sign tells us the direction.","In everyday situations, positive may represent a rise, deposit, height above a reference point or movement in one chosen direction. Negative may represent a fall, debt, depth below a reference point or movement in the opposite direction.","The meaning depends on the reference chosen in the question, so read the context before calculating."],board:["+6  means 6 units in the positive direction","−6  means 6 units in the negative direction","","On a number line:","← negative values     0     positive values →"],examples:[{q:"A lift is 4 floors below ground level. Represent its position as a directed number.",steps:["Take ground level as 0.","Below ground is the negative direction.","Four floors below ground is therefore −4."],answer:"−4"},{q:"A bank account changes by a deposit of ₦7,500 and later a withdrawal of ₦2,000. Represent the two changes.",steps:["A deposit increases the balance, so represent it by a positive number: +₦7,500.","A withdrawal decreases the balance, so represent it by a negative number: −₦2,000."],answer:"+₦7,500 and −₦2,000"}]},
{title:"2. Prerequisite bridge: moving with directed numbers",body:["Before multiplying and dividing directed numbers, recall how positive and negative changes behave on a number line. This foundation prevents sign rules from becoming disconnected facts.","Adding a positive number moves to the right; adding a negative number moves to the left. Subtracting a positive moves left. Subtracting a negative reverses that direction and is equivalent to adding the corresponding positive number."],board:["Add +a  → move right a units","Add −a  → move left a units","Subtract +a → move left a units","Subtract −a → move right a units"],examples:[{q:"Evaluate (−4)+(+9).",steps:["Start at −4.","Adding +9 means move 9 units to the right.","You arrive at +5."],answer:"+5"},{q:"Evaluate 6−(−3).",steps:["Start at +6.","Subtracting a negative reverses the negative movement.","So 6−(−3)=6+3.","Move 3 units right from 6."],answer:"+9"},{q:"Evaluate (−5)+(−4)−(−3).",steps:["Start with −5.","Add −4: move 4 units left to −9.","Subtract −3: move 3 units right.","−9+3=−6."],answer:"−6"}]},
{title:"3. Before multiplying: separate magnitude from sign",body:["When multiplying directed numbers, first calculate the magnitude using the ordinary multiplication facts you already know. Then determine the sign of the product.","For example, in (−4)×(+3), the magnitudes are 4 and 3, so the magnitude of the product is 12. The remaining question is whether that 12 is positive or negative. We establish that sign rule next.","We are not throwing the signs away. We are separating two jobs so the learner can see them: ordinary multiplication determines the size; the directed signs determine the direction of that size."],board:["For every directed-number multiplication","1. Read the sign of EACH factor.","2. Multiply the magnitudes to find the size.","3. Decide the sign from the sign relationship.","4. Attach that sign to the magnitude.","5. Check that the result follows the sign rule already established."],examples:[{q:"What is the magnitude of (−8)×(+7) before deciding its sign?",steps:["Ignore the signs only for the magnitude step.","8×7=56.","Now keep 56 ready while the sign is determined."],answer:"Magnitude = 56"}]},
{title:"3. Why positive × negative is negative",body:["Multiplication can represent repeated equal changes. Three groups of a change of −4 means the negative change occurs three times.","That gives (−4)+(−4)+(−4)=−12. Therefore a positive number of groups of a negative quantity gives a negative product."],board:["(+3) × (−4)","= (−4) + (−4) + (−4)","= −12","","So:  positive × negative = negative"],examples:[{q:"Calculate (+5)×(−6).",steps:["The magnitude is 5×6=30.","Five groups of −6 move 6 units negatively five times.","Therefore the product has a negative sign."],answer:"(+5)×(−6)=−30"},{q:"A temperature changes by −2°C each hour for 6 hours. What is the total change?",steps:["Each hourly change is −2°C.","There are 6 equal changes, so calculate 6×(−2).","Magnitude: 6×2=12.","Positive number of negative changes gives a negative result."],answer:"Total change = −12°C"}]},
{title:"4. Why negative × positive is negative",body:["The order of factors does not change a product. Since (+3)×(−4)=−12, reversing the factors gives (−4)×(+3)=−12.","You can also see the pattern by decreasing the first factor one step at a time while multiplying by +3."],board:["(+2)×(+3)=+6","(+1)×(+3)=+3","0×(+3)=0","(−1)×(+3)=−3","(−2)×(+3)=−6","","So:  negative × positive = negative"],examples:[{q:"Calculate (−9)×(+4).",steps:["Multiply magnitudes: 9×4=36.","The signs are different: negative and positive.","Different signs give a negative product."],answer:"−36"},{q:"Evaluate −15×3.",steps:["Read both factors before calculating. One factor is negative and the other is positive, so their signs are different.","First find the magnitude using ordinary multiplication: 15×3=45.","Now determine direction. The established sign rule says different signs give a negative product.","Attach the negative sign to the magnitude 45.","Therefore the product is −45. As a check, this agrees with the negative×positive pattern already derived."],answer:"−45"}]},
{title:"5. Why negative × negative is positive",body:["This rule should not appear as something to memorise without reason. Continue a multiplication pattern while the first factor decreases by 1.","Each line below must decrease by the same amount. Because the second factor is −3, decreasing the first factor by 1 makes the product increase by 3. The pattern therefore passes from 0 to positive values."],board:["(+2)×(−3)=−6","(+1)×(−3)=−3","0×(−3)=0","(−1)×(−3)=+3","(−2)×(−3)=+6","","Therefore:  negative × negative = positive"],examples:[{q:"Calculate (−7)×(−8).",steps:["Multiply magnitudes: 7×8=56.","Both factors have the same negative sign.","Negative × negative gives a positive product."],answer:"+56"},{q:"Evaluate (−12)(−5).",steps:["Brackets written side by side mean multiplication.","Magnitude: 12×5=60.","Both signs are negative, so the product is positive."],answer:"60"}]},
{title:"6. Multiplication sign rules — now state the complete rule",body:["Only after seeing why the cases behave as they do do we collect them into one rule. Same signs give a positive product; different signs give a negative product.","The sign rule does not replace multiplication. Determine the sign and still multiply the magnitudes accurately."],board:["(+ ) × (+ ) = +","(+ ) × (− ) = −","(− ) × (+ ) = −","(− ) × (− ) = +","","Same signs → positive","Different signs → negative"],examples:[{q:"Evaluate (−14)×(+6).",steps:["Signs are different, so the answer is negative.","14×6=84."],answer:"−84"},{q:"Evaluate (−25)×(−4).",steps:["Signs are the same, so the answer is positive.","25×4=100."],answer:"+100"},{q:"Evaluate (+18)×(+7).",steps:["Both signs are positive, so the product is positive.","18×7=126."],answer:"+126"}]},
{title:"7. Division is the inverse of multiplication",body:["Division asks a multiplication question in reverse. For example, 24÷6 asks: 6 multiplied by what number gives 24?","We use that inverse relationship to establish the signs in division rather than introducing another unexplained table of rules."],board:["24 ÷ 6 = 4  because  6 × 4 = 24","","For directed numbers:","Dividend ÷ Divisor = Quotient","because","Divisor × Quotient = Dividend"],examples:[{q:"Find −24÷(+6) by thinking backwards.",steps:["Ask: (+6) multiplied by what number gives −24?","6×4 has magnitude 24.","To make the product negative, the missing factor must be negative.","(+6)×(−4)=−24."],answer:"−24÷(+6)=−4"},{q:"Find −35÷(−7) by thinking backwards.",steps:["Ask: (−7) multiplied by what number gives −35?","7×5=35.","A negative product from −7 requires a positive second factor.","(−7)×(+5)=−35."],answer:"−35÷(−7)=+5"}]},
{title:"8. Division sign rules — derived from multiplication",body:["Because division reverses multiplication, it follows the same sign pattern: same signs give a positive quotient and different signs give a negative quotient.","Always divide the magnitudes as well as determining the sign."],board:["(+ ) ÷ (+ ) = +","(+ ) ÷ (− ) = −","(− ) ÷ (+ ) = −","(− ) ÷ (− ) = +","","Same signs → positive","Different signs → negative"],examples:[{q:"Evaluate −84÷12.",steps:["The signs are different, so the quotient is negative.","84÷12=7."],answer:"−7"},{q:"Evaluate −84÷(−12).",steps:["The signs are the same, so the quotient is positive.","84÷12=7."],answer:"+7"},{q:"Evaluate 144÷(−9).",steps:["The signs are different, so the answer is negative.","144÷9=16."],answer:"−16"}]},
{title:"9. More than two factors: determine the final sign carefully",body:["For several factors, work from left to right or count negative factors. Every pair of negative factors contributes a positive sign.","An even number of negative factors gives a positive product. An odd number gives a negative product. This shortcut comes from repeatedly applying the two-factor rule."],board:["Two negative factors → positive","Three negative factors → negative","Four negative factors → positive","","Even number of negative factors → +","Odd number of negative factors → −"],examples:[{q:"Evaluate (−2)×(−3)×(+5).",steps:["Work from left to right so only two factors are handled at a time.","First consider (−2)×(−3). The signs are the same, so this product is positive; 2×3=6. Therefore (−2)×(−3)=+6.","The expression is now (+6)×(+5).","Both remaining factors are positive, so the final product is positive.","6×5=30, giving +30.","As a sign check, the original expression contained two negative factors—an even number—so a positive final sign is expected."],answer:"+30"},{q:"Evaluate (−2)×(−3)×(−4).",steps:["First: (−2)×(−3)=+6.","Then: +6×(−4)=−24.","There are three negative factors, an odd number, so the final sign is negative."],answer:"−24"},{q:"Evaluate (−120)÷(−5)÷(−3).",steps:["Division operations of equal priority are performed from left to right.","Begin with −120÷(−5). The signs are the same, so the quotient is positive.","120÷5=24, therefore −120÷(−5)=+24.","Now divide that result by −3: +24÷(−3).","The signs are different, so this quotient is negative.","24÷3=8, therefore the final answer is −8."],answer:"−8"}]},
{title:"10. Brackets and operation order",body:["Brackets help show which signed numbers belong together. A negative sign attached to a number is part of that number.","When an expression contains several operations, calculate multiplication and division before addition and subtraction unless brackets require another order."],board:["Brackets first","Then multiplication and division","Then addition and subtraction"],examples:[{q:"Evaluate 8+(−3)×4.",steps:["The expression contains addition and multiplication. Multiplication has higher priority, so do (−3)×4 before adding 8.","For (−3)×(+4), the signs are different, so the product is negative.","3×4=12, therefore (−3)×4=−12.","Now return to the addition: 8+(−12).","Adding a negative 12 means move 12 units left from 8, which is the same as 8−12.","8−12=−4."],answer:"−4"},{q:"Evaluate (−18÷3)×(−2).",steps:["Work inside the bracket: −18÷3=−6.","Then multiply: (−6)×(−2).","Same signs give positive; 6×2=12."],answer:"+12"}]},
{title:"11. Directed numbers in records and schedules",body:["The curriculum also expects learners to interpret information from tables, charts, records and schedules. First read the heading, unit and reference point. Then decide what positive and negative values mean in that particular record.","Do not invent a sign meaning. A negative temperature, negative balance change and negative height may all use the same symbol but describe different situations."],examples:[{q:"A temperature record shows −4°C at 6 a.m. and +8°C at noon. Find the rise.",steps:["Initial temperature=−4°C.","Final temperature=+8°C.","Change=final−initial.","=8−(−4).","Subtracting a negative gives 8+4=12."],answer:"Temperature rose by 12°C"},{q:"A record shows changes of +₦5,000, −₦2,500, −₦1,000 and +₦3,000. Find the net change.",steps:["Add positive changes: ₦5,000+₦3,000=₦8,000.","Add the magnitudes of negative changes: ₦2,500+₦1,000=₦3,500.","Net change=₦8,000−₦3,500=+₦4,500."],answer:"Net increase = ₦4,500"}]},
{title:"12. Interpreting a table before calculating",body:["A table organises information in rows and columns. Locate the correct row and column and check the unit before using a value.","When comparing two entries, decide whether the question asks for a difference, total, rate, product or quotient."],examples:[{q:"A store record shows Monday change −6 units, Tuesday +9 units, Wednesday −3 units and Thursday +12 units. What is the total change?",steps:["Write the directed sum: −6+9−3+12.","−6+9=+3.","+3−3=0.","0+12=+12."],answer:"Total change = +12 units"},{q:"A machine loses 4 units of value each month for 7 months. Represent the total change.",steps:["Each month is a change of −4 units.","Seven months means seven equal negative changes.","7×(−4)=−28."],answer:"Total change = −28 units"}]},
{title:"13. Squares and square roots: recall before using a table",body:["The curriculum includes obtaining squares and square roots from tables. A table is a lookup tool; it does not replace the meaning already learned.","A square means multiplying a number by itself. A square root reverses that operation. Knowing this lets you detect a wrong table entry or a value read from the wrong row."],board:["Square:  a² = a × a","","Square root:","If a² = b, then √b = a  for the positive root used here"],examples:[{q:"Before using a table, estimate where √50 should lie.",steps:["7²=49 and 8²=64.","50 lies between 49 and 64.","Therefore √50 must lie between 7 and 8.","Any table value outside that interval must have been read incorrectly."],answer:"7 < √50 < 8"},{q:"A table gives √144. What exact value should you expect?",steps:["Recall that 12×12=144.","Therefore 144 is a perfect square.","Its positive square root is exactly 12."],answer:"√144=12"}]},
{title:"14. How to use a square or square-root table",body:["Printed mathematical tables differ slightly in layout, so follow the headings of the actual table provided. The general method is stable: identify the number required, locate its row and column according to the table headings, read the corresponding value, then check whether its size is reasonable.","If the table gives an approximate decimal, copy only the precision required by the question and do not pretend the table value is exact when it has been rounded."],board:["1. Identify the number required.","2. Read the table headings.","3. Locate the correct row/column.","4. Read the square or square-root entry.","5. Check its size using known nearby squares."],examples:[{q:"A square-root table gives √70≈8.367. How can you quickly check the entry?",steps:["8²=64 and 9²=81.","Since 70 lies between 64 and 81, √70 must lie between 8 and 9.","8.367 lies between 8 and 9, so its size is reasonable.","A more precise multiplication check would give a value close to 70."],answer:"The table value is reasonable"},{q:"A learner reads √35 as 6.42 from a table. Show why the reading must be wrong.",steps:["5²=25 and 6²=36.","Since 35 is below 36, √35 must be below 6.","6.42 is above 6, so it cannot be √35.","The learner should return to the table headings and locate the correct entry."],answer:"6.42 is impossible for √35"}]},
{title:"15. Quantitative reasoning: choose the operation from the situation",body:["A directed-number problem may not tell you to multiply or divide. Look for repeated equal changes when multiplication is appropriate, or ask how many equal signed groups are contained in a total when division is appropriate.","Translate the words into a directed-number statement before calculating."],examples:[{q:"A diver descends 3 m each minute for 8 minutes. Represent the total change in position.",steps:["Choose upward as positive, so downward is negative.","Each minute's change is −3 m.","Eight equal changes give 8×(−3).","Magnitude=8×3=24; signs give a negative result."],answer:"−24 m"},{q:"A total change of −42 points occurred equally over 6 rounds. Find the change per round.",steps:["Total directed change=−42.","Six equal rounds means divide by +6.","−42÷+6 has different signs, so the quotient is negative.","42÷6=7."],answer:"−7 points per round"},{q:"A debt changes by −₦2,500 each week for 4 weeks. What directed change does this represent?",steps:["Each weekly change is −₦2,500.","Four equal changes: 4×(−₦2,500).","Magnitude=₦10,000 and the direction is negative."],answer:"−₦10,000"}]},
{title:"16. Mixed mastery: explain, calculate and check",body:["Mastery means more than reciting 'same signs positive'. You should be able to explain why the sign rule applies, calculate the magnitude correctly, interpret the result in context and reverse the operation to check it.","For division, multiply the quotient by the divisor to see whether you recover the dividend. For multiplication, divide the product by one non-zero factor to recover the other."],examples:[{q:"A learner says (−48)÷(−6)=−8 because 'the number being divided is negative.' Correct the reasoning.",steps:["The sign of only one number does not determine the quotient.","Division uses both signs.","The dividend −48 and divisor −6 have the same sign.","Same signs in division give a positive quotient.","48÷6=8.","Check: (−6)×(+8)=−48."],answer:"(−48)÷(−6)=+8"},{q:"Evaluate (−5)×(+4)×(−3) and verify.",steps:["First (−5)×(+4)=−20.","Then (−20)×(−3)=+60.","Check by reversing the last multiplication: +60÷(−3)=−20, which matches the intermediate result."],answer:"+60"}]}
],mistakes:["Do not treat the sign as decoration; it carries direction.","Do not use addition/subtraction sign rules as though they were multiplication rules.","Establish the sign rule before relying on it: same signs give positive, different signs give negative for multiplication and division.","When several factors occur, do not lose a negative sign between steps.","Work multiplication and division in the correct order when other operations are present.","Read headings and units before interpreting tables, charts, records or schedules.","A square/square-root table is a lookup tool; check table entries against nearby known squares.","Do not report a rounded table value as exact.","In a word problem, define what positive and negative directions mean before calculating."]},
"Algebraic Expressions":{title:"Algebraic Expressions",objectives:["Explain variables, constants, coefficients, terms, factors and like terms","Translate words and number patterns into algebraic expressions","Simplify expressions by collecting like terms correctly","Expand algebraic expressions using the distributive law","Expand products of two binomials systematically","Factorise expressions by identifying the highest common numerical and algebraic factor","Connect expansion and factorisation as inverse processes","Use an area/quadratic box to organise products and simple quadratic expressions","Simplify algebraic fractions with monomial denominators by cancelling factors only","Substitute given values into expressions and evaluate accurately","Model JSS2 word and quantitative-reasoning problems algebraically","Check algebraic work by re-expansion or substitution"],sections:[
{title:"1. Foundation: algebra is arithmetic with quantities we may not yet know",body:["Arithmetic works with known numbers. Algebra lets a letter stand for a number that may be unknown, changing, or simply more convenient to describe with a symbol.","A letter does not mean 'nothing'. If x represents a number, every legal arithmetic rule still applies to x. For example, 3x means 3 multiplied by x; it does not mean 3+x.","Before manipulating an expression, learn to read what each part means."],board:["x = a variable","7 = a constant","5x = 5 × x","5 = coefficient of x","","Expression:  5x + 7"],examples:[{q:"In 8p−11, identify the variable, coefficient and constant.",steps:["Read the expression as 8p+(−11). It has two terms: 8p and −11.","The letter p can represent different numerical values, so p is the variable.","In 8p, the number 8 tells us how many copies of p are being multiplied/collected: 8p means 8×p. Therefore 8 is the coefficient.","The term −11 contains no variable, so its value does not change when p changes. That makes −11 the constant term.","Keep the negative sign with 11; the constant is −11, not merely 11."],answer:"Variable p; coefficient 8; constant −11"},{q:"What does 4ab mean?",steps:["Letters written beside a number represent multiplication.","4ab means 4×a×b."],answer:"4×a×b"}]},
{title:"2. Terms, signs and factors",body:["Terms are separated by addition or subtraction signs. The sign immediately before a term belongs to that term.","Factors are quantities multiplied together inside one term. Distinguishing terms from factors is essential later when simplifying fractions: factors can sometimes cancel; separate added terms cannot."],board:["Expression:  6x² − 3xy + 5","","Terms:","6x²","−3xy","+5","","Factors of −3xy include −3, x and y"],examples:[{q:"List the terms of 4a²−7a+9.",steps:["Look for the + and − signs that separate the expression.","Keep each sign with the term following it."],answer:"4a², −7a, +9"},{q:"What is the coefficient of xy in −12xy?",steps:["−12 is the numerical factor multiplying xy.","The negative sign is part of the coefficient."],answer:"−12"}]},
{title:"3. Like terms: why some terms can be collected and others cannot",body:["Like terms represent the same kind of algebraic quantity. They must have exactly the same variable part with the same powers.","Think of 3x+5x as 3 groups of x plus 5 groups of x. That makes 8 groups of x. But 3x+5x² cannot be combined because x and x² are different quantities."],board:["3x + 5x = 8x","","4a² + 7a² = 11a²","","3x + 5x²  cannot be combined"],examples:[{q:"Simplify 7x+4x−3.",steps:["7x and 4x are like terms.","7x+4x=11x.","−3 is a constant and cannot combine with an x-term."],answer:"11x−3"},{q:"Simplify 6a²−2a+5a²+7a.",steps:["Collect a² terms: 6a²+5a²=11a².","Collect a terms: −2a+7a=5a.","The powers are different, so keep the two groups separate."],answer:"11a²+5a"},{q:"Simplify 9xy−4x+3xy+7x.",steps:["9xy and 3xy are like: 12xy.","−4x and +7x are like: +3x.","xy-terms and x-terms are not like terms."],answer:"12xy+3x"}]},
{title:"4. Translating words into algebra",body:["Algebraic modelling begins by deciding what the letter represents. Then translate one phrase at a time.","Order matters. '5 less than x' means x−5, while '5 minus x' means 5−x. Reading language accurately is part of the mathematics."],board:["a number n increased by 7  → n+7","5 less than x → x−5","5 minus x → 5−x","three times y → 3y","half of p → p/2"],examples:[{q:"Write an expression for 'four more than three times a number n'.",steps:["Three times n is 3n.","Four more means add 4."],answer:"3n+4"},{q:"A boy is x years old. His sister is 3 years younger. Write her age.",steps:["Younger means subtract from the boy's age.","Three years younger than x is x−3."],answer:"x−3 years"},{q:"Write the total cost of x notebooks at ₦450 each and one pen costing ₦800.",steps:["Cost of x notebooks=450×x=450x.","Add the fixed cost of the pen, ₦800."],answer:"₦(450x+800)"}]},
{title:"5. Substitution: replacing a variable by its given value",body:["To evaluate an expression, replace each variable with its stated value. Use brackets around negative substituted values so their signs do not get lost.","Follow the normal order of operations after substitution."],examples:[{q:"Evaluate 3x²−2x+5 when x=4.",steps:["Substitute x=4: 3(4²)−2(4)+5.","Calculate the power first: 4²=16.","3×16=48.","2×4=8.","48−8+5=45."],answer:"45"},{q:"Evaluate 2a−3b when a=−4 and b=5.",steps:["Substitute using brackets: 2(−4)−3(5).","2(−4)=−8.","3(5)=15.","−8−15=−23."],answer:"−23"}]},
{title:"6. Expansion begins with the distributive law",body:["Expansion removes brackets without changing the value of an expression. The factor outside the bracket must multiply every term inside.","This works because multiplication distributes over addition and subtraction. Missing even one term changes the expression."],board:["a(b+c) = ab+ac","a(b−c) = ab−ac","","The outside factor multiplies EVERY term."],examples:[{q:"Expand 5(x+3).",steps:["Multiply 5 by x: 5×x=5x.","Multiply 5 by +3: 5×3=15.","Join the two products."],answer:"5x+15"},{q:"Expand 4(3x−5).",steps:["4×3x=12x.","4×(−5)=−20."],answer:"12x−20"},{q:"Expand −3(2x−7).",steps:["−3×2x=−6x.","−3×(−7)=+21 because negative×negative is positive."],answer:"−6x+21"}]},
{title:"7. Expand first, then collect like terms",body:["Some expressions require two different skills. First distribute into every bracket. Only after the brackets are removed should you collect terms that are truly alike.","Keeping those stages separate reduces sign errors."],examples:[{q:"Simplify 3(x+4)+2x.",steps:["Expand: 3(x+4)=3x+12.","So the expression becomes 3x+12+2x.","Collect x-terms: 3x+2x=5x."],answer:"5x+12"},{q:"Simplify 5(2a−3)−2(a+4).",steps:["First bracket: 5(2a−3)=10a−15.","Second bracket is multiplied by −2: −2(a+4)=−2a−8.","Now collect like terms: 10a−2a=8a.","Constants: −15−8=−23."],answer:"8a−23"},{q:"Simplify 4(2x−1)−3(x−5).",steps:["4(2x−1)=8x−4.","−3(x−5)=−3x+15.","Collect x-terms: 8x−3x=5x.","Constants: −4+15=11."],answer:"5x+11"}]},
{title:"8. Multiplying two binomials: every term must meet every term",body:["When both factors contain two terms, each term in the first bracket multiplies each term in the second. That produces four products before like terms are collected.","An area or quadratic box is useful because it makes the four required products visible and prevents one from being omitted."],board:["(a+b)(c+d)","","Products required:","a×c     a×d","b×c     b×d","","Then collect like terms."],examples:[{q:"Expand (x+3)(x+5).",steps:["We have two brackets multiplied together. To expand them completely, every term in the first bracket must multiply every term in the second bracket.","Start with the first term of the first bracket: +x.","Multiply +x by the first term in the second bracket, +x: (+x)×(+x)=+x².","Still using +x, multiply it by the second term, +5: (+x)×(+5)=+5x.","Now we have finished using the first term +x. Move to the second term of the first bracket: +3.","Multiply +3 by +x: (+3)×(+x)=+3x.","Then multiply +3 by +5: (+3)×(+5)=+15.","All four required products are now present: x²+5x+3x+15.","5x and 3x are like terms because both contain x to the first power. Add their coefficients: 5+3=8.","So the expanded expression is x²+8x+15."],answer:"x²+8x+15"},{q:"Expand (x−4)(x+6).",steps:["Again, every term in the first bracket must multiply both terms in the second bracket.","Begin with +x from the first bracket. Multiply it by +x, giving +x².","Use the same +x again and multiply it by +6, giving +6x.","Now move to −4, the second term in the first bracket. Its negative sign must travel with it.","Multiply −4 by +x, giving −4x.","Then multiply −4 by +6, giving −24.","Write all four products before simplifying: x²+6x−4x−24.","The middle terms are like terms: 6x−4x=2x.","Therefore the expansion is x²+2x−24."],answer:"x²+2x−24"},{q:"Expand (2x+3)(x−5).",steps:["There are two terms in each bracket, so we expect four products before collecting like terms.","Take the first term 2x. Multiply 2x by +x: 2x×x=2x².","Still using 2x, multiply it by −5: 2x×(−5)=−10x.","Now take the second term +3. Multiply +3 by +x: 3×x=3x.","Then multiply +3 by −5: 3×(−5)=−15.","Now write the four products together: 2x²−10x+3x−15.","Only −10x and +3x are like terms. Their coefficients give −10+3=−7.","So the final expansion is 2x²−7x−15."],answer:"2x²−7x−15"}]},
{title:"9. Sign-rich bracket expansion: make the route explicit",body:["When a bracket contains subtraction, treat the negative sign as part of the term. Do not drop it while moving from one multiplication to the next.","For (2−x)(3−x), the first bracket contains +2 and −x; the second contains +3 and −x. We will deliberately finish both multiplications for +2 before moving to −x."],board:["(2−x)(3−x)","","First term from first bracket: +2","(+2)(+3) = +6","(+2)(−x) = −2x","","Second term from first bracket: −x","(−x)(+3) = −3x","(−x)(−x) = +x²","","Now collect: 6−2x−3x+x²","= x²−5x+6"],examples:[{q:"Expand (2−x)(3−x).",steps:["First identify the terms. The first bracket contains +2 and −x. The second bracket contains +3 and −x.","Start with +2. It must multiply BOTH terms in the second bracket.","First: (+2)×(+3)=+6.","Second: (+2)×(−x)=−2x.","We have now finished using +2. Next take −x from the first bracket. Keep its negative sign attached.","Multiply −x by +3: (−x)×(+3)=−3x.","Then multiply −x by −x. A negative times a negative is positive, while x×x=x², so (−x)(−x)=+x².","Put all four products together before simplifying: 6−2x−3x+x².","−2x and −3x are like terms. Together they make −5x.","Write in descending powers of x: x²−5x+6."],answer:"x²−5x+6"},{q:"Expand (4−x)(2+x).",steps:["The first bracket contains +4 and −x; the second contains +2 and +x.","Use +4 first: (+4)(+2)=+8, then (+4)(+x)=+4x.","Now use −x: (−x)(+2)=−2x, then (−x)(+x)=−x².","Write every product: 8+4x−2x−x².","Collect the like x-terms: 4x−2x=2x.","In descending powers, the result is −x²+2x+8."],answer:"−x²+2x+8"}]},
{title:"9. The quadratic/area box: organise the four products",body:["A quadratic box is not a new algebra rule. It is a visual organiser for the same distributive multiplication.","Place one binomial across the top and the other down the side. Fill each cell with the product of its row and column headings, then collect like terms."],board:["Example: (x+2)(x+7)","","        x      +7","x      x²      7x","+2     2x      14","","x²+7x+2x+14","= x²+9x+14"],examples:[{q:"Use the box idea to expand (x+4)(x−3).",steps:["Four products are x², −3x, +4x and −12.","The middle products are like terms.","−3x+4x=+x."],answer:"x²+x−12"},{q:"What four entries belong in the box for (2x−1)(x+5)?",steps:["2x×x=2x².","2x×5=10x.","−1×x=−x.","−1×5=−5."],answer:"2x², 10x, −x, −5"}]},
{title:"10. Factorisation is expansion in reverse",body:["Expansion starts with a product and produces a sum. Factorisation starts with a sum of terms and rewrites it as a product.","To factorise by a common factor, find the greatest factor shared by every term, divide every term by it, and place the quotients inside a bracket."],board:["Expansion:","6x(2x+3) → 12x²+18x","","Factorisation reverses it:","12x²+18x → 6x(2x+3)"],examples:[{q:"Factorise 8x+12.",steps:["HCF of 8 and 12 is 4.","Both terms are divisible by 4.","8x÷4=2x.","12÷4=3."],answer:"4(2x+3)"},{q:"Factorise 12x²+18x.",steps:["HCF of 12 and 18 is 6.","Both terms contain x; the lowest power common to both is x.","Common factor=6x.","12x²÷6x=2x.","18x÷6x=3."],answer:"6x(2x+3)"},{q:"Factorise 15a²b−20ab².",steps:["HCF of 15 and 20 is 5.","Both terms contain a and b.","Lowest common powers are a¹ and b¹, giving common algebraic factor ab.","Common factor=5ab.","15a²b÷5ab=3a.","−20ab²÷5ab=−4b."],answer:"5ab(3a−4b)"}]},
{title:"11. Check factorisation by expanding again",body:["A factorised answer can be checked immediately: expand it. If expansion does not reproduce the original expression exactly, the factorisation is wrong.","This check is especially useful when negative terms or powers are involved."],examples:[{q:"Check whether 7x(2x−3) is a factorisation of 14x²−21x.",steps:["Expand 7x(2x−3).","7x×2x=14x².","7x×(−3)=−21x.","The expansion matches the original expression exactly."],answer:"Yes, it is correct"},{q:"A learner writes 18x²+12x=6(3x²+2x). Is this fully factorised?",steps:["The expansion is correct, but both terms inside the bracket still contain x.","The greatest common factor of the original terms is 6x, not merely 6.","Divide by 6x: 18x²÷6x=3x and 12x÷6x=2."],answer:"No; fully factorised form is 6x(3x+2)"}]},
{title:"12. Connecting simple quadratic expressions to their factors",body:["The NERDC quadratic-box work connects a quadratic expression with the two brackets that produce it. At this stage, the goal is to recognise and verify straightforward factor pairs—not to jump ahead into advanced quadratic methods.","For a monic expression x²+bx+c, look for two numbers whose product is c and whose sum is b, then verify by expansion."],board:["x² + bx + c","","Find m and n such that:","m × n = c","m + n = b","","Then test:","(x+m)(x+n)"],examples:[{q:"Factorise x²+7x+12.",steps:["We need two numbers with product 12 and sum 7.","3×4=12 and 3+4=7.","So try (x+3)(x+4).","Check by expansion: x²+4x+3x+12=x²+7x+12."],answer:"(x+3)(x+4)"},{q:"Factorise x²−x−12.",steps:["We need two numbers with product −12 and sum −1.","−4×3=−12 and −4+3=−1.","Try (x−4)(x+3).","Expand to check: x²+3x−4x−12=x²−x−12."],answer:"(x−4)(x+3)"},{q:"Which factors produce x²+2x−15?",steps:["Need product −15 and sum +2.","+5 and −3 satisfy both conditions.","Check: (x+5)(x−3)=x²−3x+5x−15=x²+2x−15."],answer:"(x+5)(x−3)"}]},
{title:"13. Algebraic fractions: understand what cancellation really means",body:["Cancellation is division by a common non-zero factor in the numerator and denominator. It is not crossing out symbols that merely look alike.","Factor first. Only quantities that multiply the whole numerator and denominator can be cancelled."],board:["12x²y / 18xy²","","12/18 = 2/3","x²/x = x","y/y² = 1/y","","Result:  2x/(3y)"],examples:[{q:"Simplify 12x²y/(18xy²).",steps:["Numerical fraction: 12/18=2/3.","x²/x=x.","y/y²=1/y.","Combine the remaining factors."],answer:"2x/(3y)"},{q:"Simplify 20a³b²/(5ab).",steps:["20÷5=4.","a³÷a=a².","b²÷b=b."],answer:"4a²b"},{q:"Simplify 18m²n/(24mn²).",steps:["18/24 reduces to 3/4.","m²/m=m.","n/n²=1/n."],answer:"3m/(4n)"}]},
{title:"14. Why you cannot cancel terms across addition",body:["In (x+4)/x, the numerator is a sum. x is not a factor of the entire numerator, so the x symbols cannot simply be crossed out.","Compare this with x(x+4)/x: here x multiplies the entire bracket, so x is a common factor and can be divided out, provided x≠0."],board:["WRONG:  (x+4)/x  →  4","","Why? x is only one TERM of the numerator.","It is not a factor of the whole numerator.","","VALID:  x(x+4)/x = x+4,  x≠0"],examples:[{q:"Can x be cancelled in (x+5)/x?",steps:["The numerator is x+5, an addition of two terms.","x does not multiply the entire numerator.","Therefore there is no common x factor to cancel."],answer:"No"},{q:"Simplify 6x(x−2)/(3x).",steps:["6/3=2.","x/x=1 for x≠0.","The remaining bracket x−2 stays intact."],answer:"2(x−2), x≠0"}]},
{title:"15. Algebraic fractions with monomial denominators",body:["A monomial denominator has one term. Simplify by identifying numerical and variable factors, reducing each common factor carefully, and retaining anything that does not cancel.","When several variables occur, compare powers of the same variable only."],examples:[{q:"Simplify 28x³y²/(35x²y).",steps:["28/35=4/5.","x³/x²=x.","y²/y=y."],answer:"4xy/5"},{q:"Simplify −24a²b³/(18ab).",steps:["−24/18=−4/3.","a²/a=a.","b³/b=b²."],answer:"−4ab²/3"},{q:"Simplify 45p⁴q/(15p²q).",steps:["45÷15=3.","p⁴÷p²=p².","q/q=1."],answer:"3p²"}]},
{title:"16. Word modelling with perimeter, area and cost",body:["Word problems test whether algebra can describe a relationship before numbers are known. Define the variable, write the mathematical relationship, substitute the algebraic quantities, then simplify.","Units remain important: perimeter is a length; area uses square units; money expressions keep their currency meaning."],examples:[{q:"A rectangle has length (x+4) cm and width x cm. Write its area.",steps:["Area=length×width.","=(x+4)x.","Distribute x: x×x=x² and x×4=4x."],answer:"x²+4x cm²"},{q:"A rectangle has length (2x+3) cm and width (x−1) cm. Write its area.",steps:["Area=(2x+3)(x−1).","2x×x=2x².","2x×(−1)=−2x.","3×x=3x.","3×(−1)=−3.","Combine −2x+3x=+x."],answer:"2x²+x−3 cm²"},{q:"A school buys x textbooks at ₦2,400 each and y exercise books at ₦650 each. Write the total cost.",steps:["Textbook cost=2400x.","Exercise-book cost=650y.","Add the two costs."],answer:"₦(2400x+650y)"}]},
{title:"17. Number patterns and quantitative reasoning",body:["An algebraic expression can describe every term of a numerical pattern. Look for what changes regularly and what stays fixed.","Test a proposed rule with several term numbers rather than trusting one match."],examples:[{q:"The sequence is 5, 8, 11, 14, ... Write the nth term.",steps:["The sequence increases by 3, so begin with 3n.","For n=1, 3n gives 3 but the first term is 5.","Add 2: 3n+2.","Check n=2: 3(2)+2=8."],answer:"3n+2"},{q:"Matchsticks form a row of joined squares: 1 square uses 4 sticks, 2 use 7, 3 use 10. Write a rule for n joined squares.",steps:["Each new square adds 3 sticks because one side is shared.","The pattern is 4,7,10,... with common difference 3.","Use 3n then adjust: at n=1, 3n=3, so add 1."],answer:"3n+1"}]},
{title:"18. Mixed multi-step algebra",body:["JSS2 mastery requires deciding which operation comes next rather than following a single memorised routine. Read the structure: brackets suggest expansion, repeated variable forms suggest collecting like terms, and a common factor suggests factorisation.","Write one legal transformation per line so signs and powers remain visible."],examples:[{q:"Simplify 3(2x−5)+4(x+2)−x.",steps:["Expand first bracket: 6x−15.","Expand second bracket: 4x+8.","Expression becomes 6x−15+4x+8−x.","Collect x-terms: 6x+4x−x=9x.","Collect constants: −15+8=−7."],answer:"9x−7"},{q:"Factorise 24x³y−36x²y².",steps:["HCF of 24 and 36 is 12.","Lowest common power of x is x².","Lowest common power of y is y.","Common factor=12x²y.","First quotient: 24x³y÷12x²y=2x.","Second quotient: −36x²y²÷12x²y=−3y."],answer:"12x²y(2x−3y)"},{q:"Evaluate 2x²−3xy+y² when x=−2 and y=3.",steps:["Substitute with brackets: 2(−2)²−3(−2)(3)+3².","(−2)²=4, so first term=8.","−3(−2)(3)=+18.","3²=9.","8+18+9=35."],answer:"35"}]},
{title:"19. Reverse reasoning: recover missing algebraic structure",body:["Harder questions may give a result and ask for a missing coefficient or factor. Work backwards using the same expansion and factorisation relationships already learned.","Do not guess from appearance; compare corresponding terms."],examples:[{q:"If 5(2x+k)=10x+35, find k.",steps:["Expand the left: 5(2x+k)=10x+5k.","Compare with 10x+35.","The constant terms must match, so 5k=35.","k=7."],answer:"7"},{q:"Complete: 18x²−30x = 6x(3x−___).",steps:["6x×3x=18x², so the first term matches.","For the second term, 6x multiplied by the missing negative number must give −30x.","30÷6=5."],answer:"5"},{q:"If (x+4)(x+k)=x²+9x+20, find k.",steps:["The constant term is 4k=20, so k=5.","Check the middle term: x·k+4x=(k+4)x=9x when k=5."],answer:"5"}]},
{title:"20. Mastery checks: explain and verify, not merely produce an answer",body:["A strong algebra answer should survive a check. Re-expand a factorised expression; substitute a convenient value into two supposedly equivalent expressions; or compare every term after expansion.","These checks catch missing bracket terms, wrong signs, illegal cancellation and incomplete factorisation."],examples:[{q:"A learner claims 4(x−3)+2x=6x−3. Diagnose the error.",steps:["Expand 4(x−3).","4 multiplies both x and −3.","That gives 4x−12, not 4x−3.","Then 4x−12+2x=6x−12."],answer:"The learner failed to multiply −3 by 4; correct result is 6x−12"},{q:"Are 3x(x+2) and 3x²+6x equivalent?",steps:["Expand 3x(x+2).","3x×x=3x².","3x×2=6x.","This exactly matches 3x²+6x."],answer:"Yes"},{q:"A learner simplifies (2x+6)/(2x) to 3. Explain why this is invalid.",steps:["The numerator is a sum, not one product.","2x is not a factor of the entire numerator 2x+6.","Factor the numerator if useful: 2(x+3)/(2x)=(x+3)/x for x≠0.","That is not generally equal to 3."],answer:"Cancellation across addition is invalid; simplified form is (x+3)/x, x≠0"}]}
],mistakes:["Do not treat a variable as decoration; it represents a number or quantity.","Keep the sign attached to its term, especially a negative coefficient.","Combine only like terms with identical variable parts and powers.","When expanding, multiply the outside factor by every term inside the bracket.","With two binomials, account for all four products before collecting like terms.","Factorisation reverses expansion; check by expanding your answer.","Use the greatest common numerical and algebraic factor when fully factorising.","Do not cancel terms joined by addition or subtraction; cancel common factors only.","Use brackets when substituting negative values.","Translate wording carefully: 'less than' can reverse the apparent order.","Keep units in word problems and distinguish length from area.","For quadratic-box work, verify proposed factors by expansion rather than guessing."]},
"Simple Equations":{title:"Simple Equations",objectives:["Understand equality as balance","Solve one-variable equations","Check solutions by substitution","Model real-life situations with equations"],sections:[
{title:"1. Equation as a balance",body:["An equation states that two expressions have equal value. Whatever valid operation you perform on one side must be performed on the other to preserve equality."]},
{title:"2. One-step and two-step equations",body:["Undo operations in reverse order while preserving the balance."],example:{q:"Solve 3x − 4 = 17.",steps:["Add 4 to both sides: 3x = 21","Divide both sides by 3: x = 7","Check: 3(7)−4=21−4=17"],answer:"x = 7"}},
{title:"3. Variables on both sides",body:["Collect variable terms on one side and constants on the other using equal operations."],example:{q:"Solve 5x + 2 = 3x + 18.",steps:["Subtract 3x from both sides: 2x+2=18","Subtract 2: 2x=16","Divide by 2: x=8","Check: 42=42"],answer:"x = 8"}},
{title:"4. Equations from words",body:["Choose a variable, translate the relationship, solve, then answer in the original context."],example:{q:"A number is doubled and 5 is added. The result is 23. Find the number.",steps:["Let the number be x","2x+5=23","2x=18","x=9"],answer:"The number is 9."}}
],mistakes:["Do not 'move' terms without understanding the inverse operation.","Always check by substitution.","Define the unknown in word problems."]},
"Linear Inequalities":{title:"Linear Inequalities",objectives:["Identify inequalities in one variable","Solve inequalities","Represent solutions on number lines","Solve inequality word problems"],sections:[
{title:"1. Inequality language",body:["< means less than, > greater than, ≤ less than or equal to, ≥ greater than or equal to. Unlike an equation, an inequality often has many solutions."]},
{title:"2. Solve like an equation—until a negative multiplication/division",body:["Adding or subtracting the same number preserves order. Multiplying or dividing both sides by a negative reverses the inequality sign."],example:{q:"Solve 3x + 2 < 14.",steps:["Subtract 2: 3x < 12","Divide by positive 3: x < 4"],answer:"x < 4"}},
{title:"3. Why the sign reverses",body:["Because −2 < 1, multiplying both by −1 gives 2 > −1. Negative multiplication reflects numbers across zero, reversing order."],example:{q:"Solve −2x ≥ 10.",steps:["Divide both sides by −2","Because the divisor is negative, reverse ≥ to ≤","x ≤ −5","Check x=−6: −2(−6)=12 ≥10"],answer:"x ≤ −5"}},
{title:"4. Number-line representation",body:["Use an open circle for < or > because the boundary is excluded. Use a filled circle for ≤ or ≥ because the boundary is included. Shade/arrow toward all allowed values."]},
{title:"5. Word problem",body:["Translate limit words carefully: 'at most' means ≤; 'at least' means ≥; 'more than' means >; 'less than' means <."],example:{q:"A bus can carry at most 54 people. There are already 38 aboard. If x more enter, form and solve an inequality.",steps:["38+x ≤54","Subtract 38: x≤16"],answer:"At most 16 more people can enter."}}
],mistakes:["Reverse the sign only when multiplying/dividing by a negative.","Open and filled circles have different meanings.","An inequality answer is usually a set/range, not one number."]},
"Graph":{title:"Graphs and the Cartesian Plane",objectives:["Identify x- and y-axes","Plot ordered pairs","Prepare tables of values","Plot and interpret linear equations","Interpret real-life linear graphs"],sections:[
{title:"1. Cartesian plane",body:["The horizontal axis is x; the vertical axis is y. They meet at the origin (0,0). An ordered pair is written (x,y): move along x first, then y."]},
{title:"2. Quadrants and plotting",body:["Signs locate points: (+,+), (−,+), (−,−), (+,−) in quadrants I–IV respectively."],example:{q:"Describe how to plot (−3,2).",steps:["Start at (0,0)","Move 3 units left because x=−3","Move 2 units up because y=2"],answer:"Plot the point at (−3,2), in quadrant II."}},
{title:"3. Table of values",body:["A linear equation links x and y. Choose x-values and calculate corresponding y-values before plotting."],example:{q:"Prepare values for y=2x+1 when x=−1,0,1,2.",steps:["x=−1: y=−2+1=−1","x=0: y=1","x=1: y=3","x=2: y=5"],answer:"Points: (−1,−1),(0,1),(1,3),(2,5)."}},
{title:"4. Plot and interpret a straight line",body:["Choose a consistent scale, label axes and units, plot accurately, then draw the straight line through the points. A point on the line satisfies the equation."]},
{title:"5. Real-life graphs",body:["In a distance-time graph, slope shows rate of change: steeper segments represent greater speed when scales are the same; horizontal distance means no change in distance."],example:{q:"A cyclist travels 30 km in 2 h at constant speed. Find the gradient/rate.",steps:["Rate = change in distance/change in time","=30/2"],answer:"15 km/h"}}
],mistakes:["Coordinates are x first, y second.","Never omit graph scale and units.","Do not join unrelated data blindly; interpret what the line means."]},
"Plane Figure/ Shapes":{title:"Plane Figures, Shapes and Scale Drawing",objectives:["State properties of parallelogram, rhombus and kite","Recognise shapes","Draw to scale","Convert actual and scaled lengths","Solve measurement problems"],sections:[
{title:"1. Properties matter more than appearance",body:["A parallelogram has both pairs of opposite sides parallel and equal; opposite angles are equal and diagonals bisect each other.","A rhombus is a parallelogram with all four sides equal; its diagonals bisect at right angles.","A kite has two pairs of adjacent equal sides; one diagonal is a line of symmetry in the usual kite and the diagonals meet at right angles."]},
{title:"2. Scale drawing",body:["A scale compares drawing length with actual length in the same units. For 1:100, 1 cm on the drawing represents 100 cm in reality."]},
{title:"3. Actual to drawing",body:["Convert units first, then apply the scale."],example:{q:"At scale 1:200, how long should a 10 m wall be on the drawing?",steps:["10 m = 1000 cm","Drawing length = 1000÷200 cm"],answer:"5 cm"}},
{title:"4. Drawing to actual",body:["Multiply drawing length by the scale denominator, then convert to a sensible unit."],example:{q:"On a 1:500 plan, two points are 7.2 cm apart. Find actual distance.",steps:["Actual = 7.2×500 cm = 3600 cm","3600 cm ÷100 =36 m"],answer:"36 m"}},
{title:"5. Measurement problem",body:["A good scale drawing states the scale, uses accurate ruler/protractor work and labels dimensions. Never measure from a diagram declared 'not to scale'."]}],mistakes:["Convert units before applying scale.","A rhombus need not be a square.","Do not classify shapes only by how they look."]},
"Angles":{title:"Angles, Polygons, Elevation and Depression",objectives:["Find angle sums in triangles and quadrilaterals","Find interior-angle sums of polygons","Distinguish elevation and depression","Use scale drawing for distance/height problems","Relate elevation and depression"],sections:[
{title:"1. Triangle and quadrilateral foundations",body:["Angles in any triangle sum to 180°. A quadrilateral can be split into two triangles, so its interior angles sum to 360°."]},
{title:"2. Polygon interior-angle sum",body:["From one vertex, an n-sided convex polygon can be divided into n−2 triangles. Therefore sum of interior angles = (n−2)×180°."],example:{q:"Find the sum of interior angles of a hexagon.",steps:["n=6","(n−2)×180°=(6−2)×180°","=4×180°"],answer:"720°"}},
{title:"3. Missing angle",body:["Use the correct total, then subtract known angles."],example:{q:"Three angles of a quadrilateral are 85°, 110° and 72°. Find the fourth.",steps:["Quadrilateral sum=360°","Known sum=85+110+72=267°","Missing=360−267"],answer:"93°"}},
{title:"4. Elevation and depression",body:["Angle of elevation is measured upward from a horizontal line of sight. Angle of depression is measured downward from a horizontal line of sight.","With parallel horizontal lines, corresponding/alternate angle relationships explain why an angle of depression can equal the corresponding angle of elevation."]},
{title:"5. Scale-drawing application",body:["At JSS2, construct the given angle and scaled distance accurately, complete the right-triangle representation, then measure the requested scaled length and convert back. Do not introduce trigonometric ratios when the curriculum asks for scale drawing."]}],mistakes:["Use (n−2)×180°, not n×180°.","Elevation/depression are measured from horizontal, not vertical.","Respect the stated scale."]},
"Bearing":{title:"Bearing",objectives:["Identify major and minor cardinal points","Locate objects using compass and three-digit bearings","Measure distances using scale drawing"],sections:[
{title:"1. Direction foundation",body:["Major cardinal points are North, East, South and West. Minor/intercardinal points include NE, SE, SW and NW."]},
{title:"2. Three-digit bearings",body:["A three-digit bearing is measured clockwise from North and written with three digits: 045°, 090°, 180°, 270°. Always begin at the north line of the starting point."]},
{title:"3. Compass bearings",body:["Compass notation describes direction from North or South toward East or West, such as N30°E. Keep it distinct from three-digit bearing notation."]},
{title:"4. Locate an object",body:["Draw North at the starting point, place the protractor centre at the point, measure clockwise, draw the bearing ray, then mark the scaled distance."],example:{q:"A clinic is 6 km from a school on bearing 060°. Use scale 1 cm : 2 km. How far is it on the drawing?",steps:["Drawing distance=6÷2 cm=3 cm","Draw North at school","Measure 060° clockwise from North","Draw a 3 cm ray"],answer:"The clinic is marked 3 cm from the school along bearing 060°."}},
{title:"5. Reverse bearing",body:["For two points, the reverse direction differs by 180°. Add 180° if the bearing is below 180°; subtract 180° if it is 180° or more."],example:{q:"If B is on bearing 070° from A, find the bearing of A from B.",steps:["070°<180°, so add 180°","70°+180°=250°"],answer:"250°"}}
],mistakes:["Bearings are measured clockwise from North.","Write three-digit bearings with leading zeros.","A distance needs a scale; a bearing alone gives direction, not distance."]},
"Construction":{title:"Geometrical Construction",objectives:["Construct triangles from sufficient measurements","Construct SSS, SAS and ASA/AAS cases","Bisect an angle accurately","Explain construction arcs"],sections:[
{title:"1. Construction is exact geometry",body:["Use ruler for straight lines, compasses for equal distances/arcs and protractor only where the specified construction permits angle measurement. Keep construction arcs visible because they show why the result is valid."]},
{title:"2. SSS triangle",body:["When all three sides are known, draw one side as base. From each endpoint draw arcs with radii equal to the other two sides. Their intersection fixes the third vertex."],example:{q:"Construct triangle ABC with AB=6 cm, AC=5 cm, BC=4 cm.",steps:["Draw AB=6 cm","Centre A, radius 5 cm: draw an arc","Centre B, radius 4 cm: draw an intersecting arc","Call intersection C","Join AC and BC","Measure sides to check"],answer:"Triangle ABC is fixed by the three side lengths."}},
{title:"3. SAS triangle",body:["Two sides and the included angle determine a triangle: draw one side, construct the included angle at the correct endpoint, mark the second side length, then join the remaining vertices."]},
{title:"4. ASA/AAS triangle",body:["Draw the known side, construct the given angle rays at the required endpoints; their intersection determines the third vertex."]},
{title:"5. Bisect an angle",body:["An angle bisector divides an angle into two equal angles."],example:{q:"Bisect ∠A using ruler and compasses.",steps:["Centre A, draw an arc cutting both arms at P and Q","With equal compass radius, draw arcs from P and Q to intersect at R","Join A to R","AR is the angle bisector because R is equally distant from P and Q"],answer:"∠PAR = ∠RAQ."}}
],mistakes:["Do not erase construction arcs.","Use the included angle in SAS correctly.","A sketch is not a construction."]},
"Data Presentation":{title:"Data Presentation",objectives:["Order data","Construct frequency tables","Read pie charts","Calculate and interpret interquartile range","Construct and compare box plots"],sections:[
{title:"1. Raw data to ordered data",body:["Raw data are observations as collected. Ordering them from least to greatest reveals position and makes quartiles easier to determine."]},
{title:"2. Frequency tables",body:["Frequency tells how many times a value/category occurs. Tally carefully and verify that total frequency equals the number of observations."],example:{q:"For 2,3,2,5,3,2,4 construct frequencies.",steps:["2 occurs 3 times","3 occurs 2 times","4 occurs 1 time","5 occurs 1 time","Total=3+2+1+1=7, matching 7 observations"],answer:"Frequencies: 2→3, 3→2, 4→1, 5→1."}},
{title:"3. Reading pie charts",body:["A full circle is 360°. Sector fraction = sector angle/360 = category frequency/total. Use this relationship in either direction."],example:{q:"A 90° sector represents books in a survey of 80 learners. How many chose books?",steps:["90/360=1/4","1/4×80=20"],answer:"20 learners"}},
{title:"4. Quartiles and IQR",body:["Q1 marks the lower quarter, Q2 is the median, Q3 marks the upper quarter. IQR=Q3−Q1 and measures the spread of the middle 50% of the data.","Use one consistent school convention for locating quartiles and state it when an even-sized data set could be treated differently."],example:{q:"For 2,4,5,7,8,10,12,14 find IQR using median-of-halves.",steps:["Lower half: 2,4,5,7 → Q1=(4+5)/2=4.5","Upper half: 8,10,12,14 → Q3=(10+12)/2=11","IQR=11−4.5"],answer:"IQR = 6.5"}},
{title:"5. Box plots",body:["A box plot uses five-number summary: minimum, Q1, median, Q3, maximum. The box spans Q1 to Q3; the line inside is the median; whiskers extend to minimum and maximum.","Compare medians for centre and IQRs for middle spread. A larger IQR means the middle half is more spread out."]}],mistakes:["Order data before finding quartiles.","IQR is Q3−Q1, not maximum−minimum.","Pie-chart angles must relate to 360°."]},
"Probability":{title:"Probability",objectives:["Discuss chance events","Determine probabilities of simple events","Use experiments with coins/dice","Apply probability to uncertain everyday events"],sections:[
{title:"1. Chance and uncertainty",body:["Probability measures how likely an event is. Probability 0 means impossible; 1 means certain; values between 0 and 1 describe degrees of likelihood."]},
{title:"2. Outcomes and events",body:["The sample space lists all possible outcomes. An event is one or more outcomes of interest. For equally likely outcomes, P(event)=favourable outcomes/total possible outcomes."],example:{q:"A fair die is rolled. Find P(rolling an even number).",steps:["Sample space={1,2,3,4,5,6}: 6 equally likely outcomes","Even outcomes={2,4,6}: 3 favourable outcomes","P(even)=3/6"],answer:"1/2"}},
{title:"3. Coin experiment",body:["Theoretical probability predicts from equally likely outcomes; experimental probability uses observed frequency. With more trials, experimental results often become more stable, but need not equal theory exactly."],example:{q:"A coin gives 27 heads in 50 tosses. Find experimental P(head).",steps:["Experimental probability=observed heads/total tosses","=27/50"],answer:"0.54 or 54%"}},
{title:"4. Complement",body:["An event and 'not the event' together cover all possibilities, so P(not A)=1−P(A)."],example:{q:"If P(rain)=0.3, find P(no rain).",steps:["P(no rain)=1−0.3"],answer:"0.7"}},
{title:"5. Everyday interpretation",body:["Probability supports decisions under uncertainty but does not guarantee a single outcome. A 70% chance does not mean the event must happen.","Use trustworthy data and define the population/time period before drawing real-life conclusions."]}],mistakes:["Probability must lie from 0 to 1 inclusive.","Do not confuse experimental frequency with certainty.","List the sample space before counting favourable outcomes."]}
};
export default function JSS2PremiumMathLesson({topic,onExercise}:{topic:string;onExercise:()=>void}){const l=lessons[topic];if(!l)return null;return <article className="wn-lesson fractions-premium-lesson"><header className="wn-hero"><span>JSS2 MATHEMATICS · NERDC SEPTEMBER 2025</span><h1>{l.title}</h1><p>Concept-first teaching, fully worked reasoning and curriculum-level application.</p></header><section className="wn-objectives"><h2>Learning Objectives</h2><ul>{l.objectives.map(x=><li key={x}>{x}</li>)}</ul></section>{l.sections.map(s=><section className="wn-section" key={s.title}><h3>{s.title}</h3>{s.body.map((p,i)=><p key={i}>{p}</p>)}{s.board&&<div className="formula-board">{s.board.map((x,i)=><div className="formula-line" key={i}>{x}</div>)}</div>}{[...(s.example?[s.example]:[]),...(s.examples||[])].map((ex,ei)=><div className="fraction-working" key={ei}><div className="example-question"><span>{ei===0?'WORKED EXAMPLE':`COMPLEMENTARY EXAMPLE ${ei+1}`}</span><strong>{ex.q}</strong></div><div className="math-stack">{ex.steps.map((x,i)=><div className="math-line" key={i}>{x}</div>)}<div className="math-line math-result">{ex.answer}</div></div></div>)}</section>)}<section className="wn-section"><h3>Common Mistakes and Misconceptions</h3><div className="lesson-rule">{l.mistakes.map(x=><span key={x}>{x}</span>)}</div></section><section className="wn-section"><h3>Mastery Standard</h3><p>Do not move on because a rule has been memorised. You should be able to explain the idea, complete the method accurately, solve an unfamiliar application and check whether the answer is reasonable.</p></section><div className="teacher-actions"><button className="primary" onClick={onExercise}>Go to Exercise →</button></div></article>}
export const jss2PremiumMathTopics=Object.keys(lessons);